function pageHasFocus(){return document.visibilityState==='visible'&&document.hasFocus()}
function saveFocus(){if(!pageHasFocus())return null;const el=document.activeElement;if(!el||!el.id||!['cpaSearch','credSearch','channelSearch','accountSearch'].includes(el.id))return null;return{id:el.id,start:el.selectionStart,end:el.selectionEnd}}
