async function connectAll(scope,opt={}){if(connectAllPromise)return connectAllPromise;connectAllPromise=(async()=>{const jobs=[];if(!scope||scope==='cpa')jobs.push(...servers.map(s=>connectSrv(s)));if(!scope||scope==='channel')jobs.push(runQueued(channels,2,c=>refreshChannel(c.id,opt)));if(!scope||scope==='account')jobs.push(...accounts.map(a=>refreshAccount(a.id,opt)));await Promise.allSettled(jobs);firstLoad=false;refreshing.clear();chRefreshing.clear();acctRefreshing.clear();renderData()})().finally(()=>{connectAllPromise=null});return connectAllPromise}
async function connectSrv(srv){if(srvConnecting.has(srv.id))return;srvConnecting.add(srv.id);srv.url=normCpaUrl(srv.url);try{const u=cpaUrl(srv,'/auth-files',{_ts:Date.now()}),r=await cpaHttp(u,{headers:{'Authorization':cpaAuth(srv),'Cache-Control':'no-cache','Pragma':'no-cache'}}),d=cpaJson(r);srv.files=d.files||[];srv.status='online';srv.error=null}catch(e){srv.status='offline';srv.files=[];srv.error=e.message||String(e)}finally{srvConnecting.delete(srv.id)}}
