function renderAccounts(){const el=document.getElementById('accountPanel');if(!el)return;const q=accountQuery.trim().toLowerCase(),list=q?accounts.filter(a=>accountSearchText(a).includes(q)):accounts,bar=`${renderAccountOverview()}<div class="search-row"><input class="fi" id="accountSearch" value="${esc(accountQuery)}" oninput="keepFocus(()=>{accountQuery=this.value;renderAccounts()})" placeholder="搜索账号 / Workspace">${ib('bp','添加','showAcctModal()')}</div>`;if(!accounts.length){el.innerHTML=bar+'<div class="empty">暂无账号，点击添加 OpenCode Go</div>';return}if(!list.length){el.innerHTML=bar+'<div class="empty">没有匹配的账号</div>';return}el.innerHTML=bar+list.map(renderAccountCard).join('')}
