function fmtResetCompact(sec){const s=Math.max(0,Number(sec)||0),d=Math.floor(s/86400),h=Math.floor(s%86400/3600),m=Math.floor(s%3600/60);if(d>0)return`${d}天${h}小时`;if(h>0)return`${h}小时${m}分`;if(m>0)return`${m}分`;return s?`${Math.floor(s)}秒`:''}
function renderUsageWindow(label,used,resetInSec,usedDollars,limitDollars){const u=Math.max(0,Math.min(100,Number(used)||0)),r=Math.max(0,100-u),c=u>70?'h':u>30?'m':'l',reset=fmtResetCompact(resetInSec),money=Number.isFinite(Number(usedDollars))&&Number.isFinite(Number(limitDollars))?`$${Number(usedDollars).toFixed(2)}/$${Number(limitDollars).toFixed(0)}`:'',detail=`已用 ${u.toFixed(0)}%${money?` · ${money}`:''}${resetInSec?` · 恢复于 ${fmtResetTime(Number(resetInSec))}`:''}`;return`<div class="acct-qi" title="${esc(detail)}"><span class="acct-ql">${esc(label)}</span><span class="acct-qv" style="color:${r<30?'var(--err)':'inherit'}">${r.toFixed(0)}%</span><span class="acct-bar"><span class="pfill ${c}" style="width:${r}%"></span></span><span class="acct-reset">${reset?`恢复 ${esc(reset)}`:''}</span></div>`}
function opencodeGoWindows(d){const item=(raw,label)=>{if(!raw||typeof raw!=='object')return null;const used=Number(raw.usagePercent??raw.usage_percent??raw.percent??raw.usedPercent);if(!Number.isFinite(used))return null;return{label,used,resetInSec:Number(raw.resetInSec??raw.resetsInSeconds??raw.resets_in_seconds??0)||0,usedDollars:raw.usageDollars??raw.usage_dollars,limitDollars:raw.limitDollars??raw.limit_dollars}};return[item(d?.rolling||d?.rolling5h||d?.rollingUsage,'5小时'),item(d?.weekly||d?.weeklyUsage,'周'),item(d?.monthly||d?.monthlyUsage,'月')].filter(Boolean)}
function parseLooseObject(text){const body=String(text||'').trim();if(!body)return null;try{return JSON.parse(body)}catch{}try{return JSON.parse(body.replace(/([{,]\s*)([a-zA-Z_][a-zA-Z0-9_]*)(\s*:)/g,'$1"$2"$3').replace(/'/g,'"'))}catch{return null}}
function parseOpenCodeGoUsageJson(value){let out=null;const visit=node=>{if(!node||out)return;if(Array.isArray(node)){node.forEach(visit);return}if(typeof node!=='object')return;const hasUsage=node.rollingUsage||node.weeklyUsage||node.monthlyUsage;if(hasUsage&&opencodeGoWindows(node).length){out={rolling:node.rollingUsage,weekly:node.weeklyUsage,monthly:node.monthlyUsage};return}Object.values(node).forEach(visit)};visit(value);return out}
function parseOpenCodeGoUsage(html){const text=String(html||'');try{const parsed=JSON.parse(text),fromJson=parseOpenCodeGoUsageJson(parsed);if(fromJson)return fromJson}catch{}const out={};for(const [key,pattern]of Object.entries({rolling:/rollingUsage:\$R\[\d+\]=(\{[^}]+\})/,weekly:/weeklyUsage:\$R\[\d+\]=(\{[^}]+\})/,monthly:/monthlyUsage:\$R\[\d+\]=(\{[^}]+\})/})){const m=text.match(pattern);if(m)out[key]=parseLooseObject(m[1])}if(opencodeGoWindows(out).length)return out;for(const key of ['rollingUsage','weeklyUsage','monthlyUsage']){const idx=text.indexOf(key);if(idx<0)continue;const start=text.indexOf('{',idx);if(start<0)continue;let depth=0,end=-1;for(let i=start;i<Math.min(text.length,start+1200);i++){const ch=text[i];if(ch==='{')depth++;else if(ch==='}'){depth--;if(depth===0){end=i;break}}}if(end>start){const parsed=parseLooseObject(text.slice(start,end+1));if(parsed)out[key.replace('Usage','')]=parsed}}if(opencodeGoWindows(out).length)return out;throw new Error('未解析到 OpenCode Go 额度数据')}
const OPENCODE_WORKSPACES_SERVER_ID='def39973159c7f0483d8793a822b8dbb10d067e12c65455fcb4608459ba0234f';
function acctHeaders(a,kind='page'){let cookie=cleanCookieText(a.cookie||'');if(cookie&&!/\bauth=/i.test(cookie))cookie='auth='+cookie;const h={'Accept':kind==='server'?'text/javascript, application/json;q=0.9, */*;q=0.8':'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8','Cookie':cookie};if(kind==='server'){const uuid=globalThis.crypto?.randomUUID?.()||String(Date.now())+Math.random().toString(16).slice(2);h['X-Server-Id']=OPENCODE_WORKSPACES_SERVER_ID;h['X-Server-Instance']='server-fn:'+uuid;h['Content-Type']='application/json'}return h}
function normalizeOpenCodeWorkspaceId(value){const s=cleanSecretText(value||''),m=s.match(/wrk_[a-zA-Z0-9]+/);return m?m[0]:''}
function collectWorkspaceIds(value,out=new Set()){if(value==null)return out;if(typeof value==='string'){for(const m of value.matchAll(/wrk_[a-zA-Z0-9]+/g))out.add(m[0]);return out}if(Array.isArray(value)){value.forEach(v=>collectWorkspaceIds(v,out));return out}if(typeof value==='object'){Object.values(value).forEach(v=>collectWorkspaceIds(v,out));return out}return out}
function extractWorkspaceId(value){return Array.from(collectWorkspaceIds(value))[0]||''}
function looksOpenCodeSignedOut(text){const l=String(text||'').toLowerCase();return l.includes('please log in')||l.includes('sign in to')||l.includes('auth/authorize')||l.includes('not associated with an account')||l.includes('actor of type "public"')}
async function discoverOpenCodeWorkspaceFromServer(a){const base=`https://opencode.ai/_server?id=${encodeURIComponent(OPENCODE_WORKSPACES_SERVER_ID)}`;let res=await chHttp(base,{kind:'account',headers:acctHeaders(a,'server')});if(res.status===401||res.status===403)throw new Error('认证失败，请检查 auth cookie');let body=res.body||'';if(looksOpenCodeSignedOut(body))throw new Error('认证失败，请检查 auth cookie');let id=extractWorkspaceId(body);if(id)return id;res=await chHttp('https://opencode.ai/_server',{kind:'account',method:'POST',headers:acctHeaders(a,'server'),body:'[]'});if(res.status===401||res.status===403)throw new Error('认证失败，请检查 auth cookie');body=res.body||'';if(looksOpenCodeSignedOut(body))throw new Error('认证失败，请检查 auth cookie');id=extractWorkspaceId(body);if(!id&&res.error)throw new Error(res.error);return id}
async function discoverOpenCodeWorkspaceFromAuth(a){const res=await chHttp('https://opencode.ai/auth',{kind:'account',headers:acctHeaders(a)});if(!res.ok){if(res.status===401||res.status===403)throw new Error('认证失败，请检查 auth cookie');throw new Error(`Auth HTTP ${res.status}${res.error?': '+res.error:''}`)}let body=res.body;try{body=JSON.parse(body)}catch{}return extractWorkspaceId(body)}
async function discoverOpenCodeWorkspace(a){const first=await discoverOpenCodeWorkspaceFromServer(a).catch(()=>''),id=first||await discoverOpenCodeWorkspaceFromAuth(a).catch(()=>''),norm=normalizeOpenCodeWorkspaceId(id);if(!norm)throw new Error('未自动发现 Workspace ID，请打开 opencode.ai/workspace/.../go 后重试或手动填写');a.workspaceId=norm;return norm}
async function fetchOpenCodeGo(a){let workspaceId=normalizeOpenCodeWorkspaceId(a.workspaceId||'');if(a.workspaceId&&!workspaceId)throw new Error('Workspace ID 格式应为 wrk_ 开头，也可以粘贴完整 workspace URL');if(!workspaceId)workspaceId=await discoverOpenCodeWorkspace(a);const url=`https://opencode.ai/workspace/${encodeURIComponent(workspaceId)}/go`,res=await chHttp(url,{kind:'account',headers:acctHeaders(a)});if(!res.ok){if(res.status===401||res.status===403)throw new Error('认证失败，请检查 auth cookie');throw new Error(`HTTP ${res.status}${res.error?': '+res.error:''}`)}a.workspaceId=workspaceId;return parseOpenCodeGoUsage(res.body)}
async function connectAccount(a){if(accountSyncing.has(a.id))return;accountSyncing.add(a.id);try{if(a.provider!=='opencode-go')throw new Error('暂仅支持 OpenCode Go');if(!a.cookie)throw new Error('请填写 auth cookie');a.data=await fetchOpenCodeGo(a);a.status='online';a.error=null;a.updatedAt=Date.now()}catch(e){a.status='offline';a.data=null;a.error=e?.message||String(e);a.updatedAt=Date.now()}finally{accountSyncing.delete(a.id);persistAccounts()}}
async function refreshAccount(id,opt={}){const a=accounts.find(x=>x.id===id);if(!a||acctRefreshing.has(id)||(opt.autoOnly&&!acctAutoEnabled(a)))return;acctRefreshing.add(id);renderData();try{await connectAccount(a)}finally{acctRefreshing.delete(id);renderData()}}
function showAcctModal(id){editAcctId=id||null;acctSaving=false;acctMenuId=null;document.querySelectorAll('.srv-menu').forEach(x=>x.classList.add('hidden'));const a=accounts.find(x=>x.id===id);document.getElementById('acctMt').textContent=a?'编辑账号':'添加账号';document.getElementById('acctName').value=a?.name||'';document.getElementById('acctProvider').value=a?.provider||'opencode-go';document.getElementById('acctWorkspaceId').value=a?.workspaceId||'';document.getElementById('acctCookie').value=a?.cookie||'';setAcctSaveBusy(false);document.getElementById('acctModal').classList.remove('hidden');setTimeout(()=>document.getElementById('acctName')?.focus(),0)}
function closeAcctModal(){document.getElementById('acctModal').classList.add('hidden');editAcctId=null;setAcctSaveBusy(false)}
function hideAcctModal(){if(acctSaving)return;closeAcctModal()}
function setAcctSaveBusy(v){acctSaving=v;const b=document.getElementById('acctSaveBtn');if(b){b.disabled=v;b.innerHTML=v?'<span class="ld" style="width:14px;height:14px;border-width:2px"></span>':icon('i-check');b.dataset.iconized='保存';b.classList.add('icon-only','icon-btn')}}
function saveAcct(){if(acctSaving)return;const name=document.getElementById('acctName').value.trim(),provider=document.getElementById('acctProvider').value,workspaceId=normalizeOpenCodeWorkspaceId(document.getElementById('acctWorkspaceId').value),cookie=cleanCookieText(document.getElementById('acctCookie').value);if(!name){alert('请填写名称');return}if(provider!=='opencode-go'){alert('当前仅支持 OpenCode Go');return}if(!cookie){alert('请填写 auth cookie');return}setAcctSaveBusy(true);let target=null,isEdit=!!editAcctId;try{const next={name,provider,workspaceId,cookie,status:null,data:null,error:null};if(editAcctId){target=accounts.find(x=>x.id===editAcctId);if(target){next.autoRefresh=acctAutoEnabled(target);Object.assign(target,next)}}else{next.autoRefresh=true;target={id:'acct_'+Date.now(),...next};accounts.push(target)}if(!target)throw new Error('账号不存在');persistAccounts();closeAcctModal();showToast(isEdit?'账号已保存，正在刷新':'账号已添加，正在刷新');renderCur()}catch(e){showToast('保存失败: '+(e.message||e));renderCur();return}finally{setAcctSaveBusy(false)}connectAccount(target).then(()=>renderCur()).catch(()=>renderCur())}
function delAcct(id){acctMenuId=null;const a=accounts.find(x=>x.id===id);if(!a)return;if(!confirm(`确定要删除账号 "${a.name}" 吗？`))return;accounts=accounts.filter(x=>x.id!==id);persistAccounts();showToast('账号已删除');renderCur()}
function toggleAcctAutoRefresh(id){const a=accounts.find(x=>x.id===id);if(!a)return;a.autoRefresh=!acctAutoEnabled(a);persistAccounts();showToast(a.autoRefresh?'自动刷新已开启':'自动刷新已关闭');renderCur()}

/* ============ CREDENTIALS PANEL ============ */
function fileActive(f){return(f.status==='ready'||f.status==='active')&&!f.disabled}
function serverStats(files){files=files||[];return{total:files.length,active:files.filter(fileActive).length,disabled:files.filter(f=>f.disabled).length,error:files.filter(f=>!fileActive(f)&&!f.disabled).length,providers:getPS(files)}}
function providerChips(ps){return Object.entries(ps||{}).map(([p,c])=>`<span class="bdg ${bc[p]||''}">${esc(p)} ${c}</span>`).join('')}
function cpaSearchText(s){return [s.name,s.url,...(s.files||[]).flatMap(f=>[f.name,f.email,f.account,f.provider])].join(' ').toLowerCase()}
function renderCpaOverview(){const online=servers.filter(s=>s.status==='online').length,files=servers.flatMap(s=>s.files||[]),st=serverStats(files),q=globalQuotaSummary();return`<div class="overview"><div class="ov-grid cpa-overview-grid"><div><div class="ov-k">CPA</div><div class="ov-v">${online}/${servers.length}</div></div><div><div class="ov-k">凭证</div><div class="ov-v" title="凭证总数">${st.total}</div></div><div><div class="ov-k">凭证状态</div>${credStateNums(st)}</div><div><div class="ov-k">限额（最低）</div>${renderQuotaChips(q.items,'暂无已刷新限额')}</div></div></div>`}

function credNums(st){return`<div class="cred-nums" title="总数 / 正常 / 异常 / 禁用"><span>${st.total}</span><em>/</em><span class="num-ok">${st.active}</span><em>/</em><span class="num-err">${st.error}</span><em>/</em><span class="num-warn">${st.disabled}</span></div>`}
function credStateNums(st){return`<div class="cred-nums" title="正常 / 异常 / 禁用"><span class="num-ok">${st.active}</span><em>/</em><span class="num-err">${st.error}</span><em>/</em><span class="num-warn">${st.disabled}</span></div>`}
function renderQuotaChips(items,empty='暂无可汇总数据'){if(!items.length)return`<span class="quota-chip muted">${empty}</span>`;let chips=items.slice(0,5).map(x=>`<span class="quota-chip ${x.min<30?'low':''}" title="${esc(x.label)} · 最低 ${x.min.toFixed(0)}% · 平均 ${x.avg.toFixed(0)}% · ${x.count} 个凭证">${esc(x.label)} <strong>${x.min.toFixed(0)}%</strong></span>`).join('');if(items.length>5)chips+=`<span class="quota-chip muted">+${items.length-5}</span>`;return chips}
function globalQuotaSummary(){const groups={};servers.forEach(s=>srvQuotaSummary(s).items.forEach(x=>{const g=groups[x.label]||(groups[x.label]={label:x.label,count:0,sum:0,min:101});g.count+=x.count;g.sum+=x.avg*x.count;g.min=Math.min(g.min,x.min)}));return{items:Object.values(groups).map(g=>({label:g.label,count:g.count,avg:g.sum/g.count,min:g.min})).sort((a,b)=>a.min-b.min||b.count-a.count)}}
function renderCred(){
  const el=document.getElementById('credPanel');
  if(cpaView){renderCredDetail();return}
  const q=cpaQuery.trim().toLowerCase();
  let list=q?servers.filter(s=>cpaSearchText(s).includes(q)):servers;
  const bar=`${renderCpaOverview()}<div class="search-row"><input class="fi" id="cpaSearch" value="${esc(cpaQuery)}" oninput="keepFocus(()=>{cpaQuery=this.value;renderCred()})" placeholder="搜索 CPA / 地址 / 凭证 / 提供商">${ib('bp','新增 CPA','showAddModal()')}</div>`;
  if(!servers.length){el.innerHTML=bar+'<div class="empty">暂无 CPA，点击添加 CPA</div>';return}
  if(!list.length){el.innerHTML=bar+'<div class="empty">没有匹配的 CPA</div>';return}
  el.innerHTML=bar+list.map(s=>renderCredSrv(s,'all','all')).join('');
}
function renderFC(file){const p=np(file.provider),pc=bc[p]||'',act=(file.status==='ready'||file.status==='active')&&!file.disabled,sc=act?'bdg-ok':file.disabled?'bdg-warn':'bdg-err',st=file.disabled?'已禁用':file.status||'未知',acc=file.email||file.account||'-',k=ck(file._sid,file.name),c=quotaCache[k],pt=(p==='codex'?getQuotaPlanText(c):'')||getPlanText(file),il=loadingFiles.has(k),tl=togglingCreds.has(k),hep=!!EP[p],canRef=hep&&!file.disabled,lrf=file.last_refresh||file.lastRefreshedAt||'',sm=String(file.status_message||file.statusMessage||'').trim(),showSm=sm&&sm.toLowerCase()!=='ok'&&sm!==st,smc=act?'var(--t2)':file.disabled?'var(--warn)':'var(--err)',tgl=file.disabled?'启用':'禁用',tglBusy=file.disabled?'启用中':'禁用中';let qH='';if(il)qH='<div class="qload"><span class="ld"></span>获取中</div>';else if(c)qH=renderQC(p,c);else if(file.disabled)qH='<div class="qempty" style="cursor:default">凭证已禁用</div>';else if(canRef)qH=`<div class="qempty" onclick="event.stopPropagation();refSingle('${file._sid}','${esc(file.name)}')">${act?'点击获取限额':'点击重试刷新'}</div>`;else if(!hep)qH='<div class="qempty" style="cursor:default">不支持限额查询</div>';else qH='<div class="qempty" style="cursor:default">账户不可用</div>';return`<div class="fc"><div class="fc-top"><div class="fc-line1"><span class="fc-name" title="${esc(file.name)}">${esc(file.name)}</span><div class="fc-acts">${canRef?`<button class="b bs" onclick="event.stopPropagation();refSingle('${file._sid}','${esc(file.name)}')" ${il||tl?'disabled':''}>${il?'<span class="ld" style="width:8px;height:8px;border-width:1.5px"></span>':'刷新'}</button>`:''}<button class="b ${file.disabled?'bp':'bd'}" onclick="event.stopPropagation();setCredDisabled('${file._sid}','${esc(file.name)}',${file.disabled?'false':'true'})" ${tl?'disabled':''}>${tl?`<span class="ld" style="width:8px;height:8px;border-width:1.5px"></span> ${tglBusy}`:tgl}</button><button class="b bs" onclick="event.stopPropagation();dlFile('${file._sid}','${esc(file.name)}')" ${tl?'disabled':''}>下载</button></div></div><div class="fc-line2"><span class="bdg ${pc}">${esc(p||'-')}</span>${pt?`<span class="bdg bdg-plan">${esc(fmtPlan(pt))}</span>`:''}<span class="bdg ${sc}">${st}</span>${lrf?`<span style="font-size:10px;color:var(--t2)" title="Token 刷新时间">刷新 ${fmtTs(lrf)}</span>`:''}</div><div class="fc-acc">${esc(acc)}</div>${showSm?`<div style="font-size:11px;color:${smc};margin-top:4px;word-break:break-word" title="${esc(sm)}">${esc(sm)}</div>`:''}<div class="fc-sep"></div></div><div class="fc-body">${qH}</div></div>`}

function renderCredSrv(srv,pf,sf){
  const connecting=srv.status===null,on=srv.status==='online',files=srv.files||[],ac=files.filter(f=>(f.status==='ready'||f.status==='active')&&!f.disabled).length,dc=files.filter(f=>f.disabled).length,ec=files.filter(f=>f.status!=='ready'&&f.status!=='active'&&!f.disabled).length;
  const ps=getPS(files),pb=Object.entries(ps).map(([p,c])=>`<span class="bdg ${bc[p]||''}">${esc(p)} ${c}</span>`).join(''),site=esc(cpaManagementUrl(srv));
  const quota=renderSrvQuotaSummary(srv);
  return`<div class="ss sortable-card" draggable="true" ondragstart="cardDragStart('cpa',${jsArg(srv.id)},event)" ondragover="cardDragOver('cpa',${jsArg(srv.id)},event)" ondragleave="cardDragLeave(event)" ondrop="dropCard('cpa',${jsArg(srv.id)},event)" ondragend="cardDragEnd()"><div class="sb cpa-head"><div class="cpa-main"><div class="cpa-title"><span class="dot ${on?'on':'off'}"></span><span class="cpa-name">${esc(srv.name)}</span><a class="site-link cpa-site" href="${site}" target="_blank" rel="noopener noreferrer">${esc(maskUrl(srv.url))}</a></div><div class="cpa-meta">${credNums({total:files.length,active:ac,error:ec,disabled:dc})}${pb}</div>${quota}</div><div class="s-act cpa-actions">${ib('bs','凭证',`showCredView('${srv.id}')`,!on?'disabled':'')}${ib('bs','API Key',`showApiKeyModal('${srv.id}')`,!on?'disabled':'')}${refreshing.has(srv.id)?`<button class="b bs icon-btn" disabled title="刷新限额" aria-label="刷新限额"><span class="ld" style="width:14px;height:14px;border-width:2px"></span></button>`:ib('bs','刷新限额',`refSQ('${srv.id}')`,!on?'disabled':'')}${ib('bs','更多',`toggleSrvMenu('${srv.id}',event)`)}${renderSrvMenu(srv.id)}</div></div></div>`}

function renderSrvMenu(id){return`<div class="srv-menu hidden" id="srvMenu_${id}"><button class="srv-menu-item" onclick="showSrvSettings('${id}')">${icon('i-settings')}<span>设置</span></button><button class="srv-menu-item" onclick="showEditModal('${id}')">${icon('i-edit')}<span>编辑</span></button><button class="srv-menu-item danger" onclick="delSrv('${id}')">${icon('i-trash')}<span>删除</span></button></div>`}
function toggleSrvMenu(id,ev){ev?.stopPropagation?.();const el=document.getElementById('srvMenu_'+id),next=el&&!el.classList.contains('hidden')?null:id;document.querySelectorAll('.srv-menu').forEach(x=>x.classList.add('hidden'));srvMenuId=next;chMenuId=null;acctMenuId=null;if(next)document.getElementById('srvMenu_'+next)?.classList.remove('hidden')}

function renderSrvQuotaSummary(srv){const q=srvQuotaSummary(srv);return`<div class="quota-line"><span class="quota-label">限额（最低）</span>${renderQuotaChips(q.items)}</div>`}
function srvQuotaSummary(srv){const groups={},files=srv.files||[];let total=0,pending=0,errors=0;files.forEach(f=>{const p=np(f.provider),k=ck(srv.id,f.name);if(!EP[p]||f.disabled)return;total++;const c=quotaCache[k];if(!c){pending++;return}if(c.error){errors++;return}quotaWindows(p,c.data).forEach(w=>{const g=groups[w.label]||(groups[w.label]={label:w.label,count:0,sum:0,min:101});g.count++;g.sum+=w.remaining;g.min=Math.min(g.min,w.remaining)})});const items=Object.values(groups).map(g=>({label:g.label,count:g.count,avg:g.sum/g.count,min:g.min})).sort((a,b)=>a.min-b.min||b.count-a.count);return{total,pending,errors,items}}
function quotaWindows(p,d){const out=[];if(!d)return out;if(p==='claude'){Object.entries(d.limits||{}).forEach(([k,v])=>{if(v&&typeof v==='object'&&'utilization'in v)out.push({label:fCWL(k),remaining:Math.max(0,100-(Number(v.utilization)||0))})})}else if(p==='codex'){const rl=d.rate_limit||d.rateLimit||{};Object.entries(rl).forEach(([k,v])=>{if(!v||typeof v!=='object')return;const used=Number(v.used_percent??v.usedPercent);if(!Number.isFinite(used))return;out.push({label:fCWL(k.replace(/_window$/,'').replace(/Window$/,'')),remaining:Math.max(0,100-used)})})}else if(p==='gemini-cli'){(d.buckets||[]).forEach(b=>out.push({label:b.model_id||b.modelId||'Gemini',remaining:Math.max(0,Number(b.remaining_fraction??b.remainingFraction??0)*100)}))}else if(p==='antigravity'){Object.entries(d.models||{}).forEach(([k,v])=>{if(v&&typeof v==='object')out.push({label:k,remaining:Math.max(0,Number(v.remaining_fraction??v.remainingFraction??0)*100)})})}else if(p==='kimi'&&Array.isArray(d)){d.forEach(i=>{const l=Number(i.limit)||0,u=Number(i.used)||0;out.push({label:i.label||i.model||'Kimi',remaining:l>0?Math.max(0,100-u/l*100):100})})}return out.filter(x=>Number.isFinite(x.remaining))}

function showCredView(id){cpaView=id;credQuery='';renderCred()}
function hideCredView(){cpaView=null;srvMenuId=null;renderCred()}
function credSearchText(f){return [f.name,f.email,f.account,f.provider,getPlanText(f)].join(' ').toLowerCase()}
function renderCredDetail(){const el=document.getElementById('credPanel'),s=servers.find(x=>x.id===cpaView);if(!s){cpaView=null;renderCred();return}const files=(s.files||[]).map(f=>({...f,_sid:s.id})),st=serverStats(files),q=credQuery.trim().toLowerCase();let ff=q?files.filter(f=>credSearchText(f).includes(q)):files;const head=`<div class="sub-head">${ib('bs back-btn','返回','hideCredView()')}<div style="min-width:0;flex:1"><div class="sub-title">${esc(s.name)} 凭证</div><div class="tm" style="font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(maskUrl(s.url))} · 凭证 ${st.total} · 正常 ${st.active} · 异常 ${st.error} · 禁用 ${st.disabled}</div></div></div><div class="search-row"><input class="fi" id="credSearch" value="${esc(credQuery)}" oninput="keepFocus(()=>{credQuery=this.value;renderCred()})" placeholder="搜索凭证 / 账号 / 提供商">${ib('bp','新增',`showAddCredModal('${s.id}')`,s.status!=='online'?'disabled':'')}${refreshing.has(s.id)?`<button class="b bs icon-btn" disabled title="刷新" aria-label="刷新"><span class="ld" style="width:14px;height:14px;border-width:2px"></span></button>`:ib('bs','刷新',`refSQ('${s.id}')`,s.status!=='online'?'disabled':'')}</div>`;if(!ff.length){el.innerHTML=head+'<div class="empty">没有匹配的凭证</div>';return}const order=['claude','codex','gemini-cli','antigravity','kimi'];const groups={};ff.forEach(f=>{const p=np(f.provider)||'unknown';(groups[p]||(groups[p]=[])).push(f)});const keys=[...order.filter(p=>groups[p]),...Object.keys(groups).filter(p=>!order.includes(p))];el.innerHTML=head+keys.map(p=>`<div class="fsec"><div class="fsec-h"><span class="bdg ${bc[p]||''}">${esc(p)}</span><span class="bdg">${groups[p].length}</span></div><div class="fg">${groups[p].map(renderFC).join('')}</div></div>`).join('')}

function renderFC(file){
  const p=np(file.provider),pc=bc[p]||'',act=(file.status==='ready'||file.status==='active')&&!file.disabled,sc=act?'bdg-ok':file.disabled?'bdg-warn':'bdg-err',st=file.disabled?'已禁用':file.status||'未知',acc=file.email||file.account||'-',k=ck(file._sid,file.name),c=quotaCache[k],pt=(p==='codex'?getQuotaPlanText(c):'')||getPlanText(file),il=loadingFiles.has(k),tl=togglingCreds.has(k),dl=deletingCreds.has(k),hep=!!EP[p],canRef=hep&&!file.disabled,lrf=file.last_refresh||file.lastRefreshedAt||'',sm=String(file.status_message||file.statusMessage||'').trim(),showSm=sm&&sm.toLowerCase()!=='ok'&&sm!==st,smc=act?'var(--t2)':file.disabled?'var(--warn)':'var(--err)',tgl=file.disabled?'启用':'禁用',tglBusy=file.disabled?'启用中':'禁用中',src=String(file.source||'').trim().toLowerCase(),rt=isRtOnly(file),canDel=!rt&&src!=='memory',delTitle=canDel?'删除凭证':rt?'运行时凭证不支持删除':'当前凭证不支持删除';
  let qH='';
  if(il)qH='<div class="qload"><span class="ld"></span>获取中</div>';
  else if(c)qH=renderQC(p,c);
  else if(file.disabled)qH='<div class="qempty" style="cursor:default">凭证已禁用</div>';
  else if(canRef)qH=`<div class="qempty" onclick="event.stopPropagation();refSingle('${file._sid}','${esc(file.name)}')">${act?'点击获取限额':'点击重试刷新'}</div>`;
  else if(!hep)qH='<div class="qempty" style="cursor:default">不支持限额查询</div>';
  else qH='<div class="qempty" style="cursor:default">账户不可用</div>';
  const dlAct=p==='codex'?`showDlCredModal('${file._sid}','${esc(file.name)}','${esc(p)}')`:`dlFile('${file._sid}','${esc(file.name)}')`;
  return`<div class="fc"><div class="fc-top"><div class="fc-line1"><span class="fc-name" title="${esc(file.name)}">${esc(file.name)}</span><div class="fc-acts">${canRef?`<button class="b bs" onclick="event.stopPropagation();refSingle('${file._sid}','${esc(file.name)}')" ${il||tl||dl?'disabled':''}>${il?'<span class="ld" style="width:8px;height:8px;border-width:1.5px"></span>':'刷新'}</button>`:''}<button class="b ${file.disabled?'bp':'bd'}" onclick="event.stopPropagation();setCredDisabled('${file._sid}','${esc(file.name)}',${file.disabled?'false':'true'})" ${tl||dl?'disabled':''}>${tl?`<span class="ld" style="width:8px;height:8px;border-width:1.5px"></span> ${tglBusy}`:tgl}</button><button class="b bs" onclick="event.stopPropagation();${dlAct}" ${tl||dl?'disabled':''}>下载</button><button class="b bd" onclick="event.stopPropagation();delCred('${file._sid}','${esc(file.name)}')" title="${esc(delTitle)}" ${!canDel||il||tl||dl?'disabled':''}>${dl?'<span class="ld" style="width:8px;height:8px;border-width:1.5px"></span> 删除中':'删除'}</button></div></div><div class="fc-line2"><span class="bdg ${pc}">${esc(p||'-')}</span>${pt?`<span class="bdg bdg-plan">${esc(fmtPlan(pt))}</span>`:''}<span class="bdg ${sc}">${st}</span>${lrf?`<span style="font-size:10px;color:var(--t2)" title="Token 刷新时间">刷新 ${fmtTs(lrf)}</span>`:''}</div><div class="fc-acc">${esc(acc)}</div>${showSm?`<div style="font-size:11px;color:${smc};margin-top:4px;word-break:break-word" title="${esc(sm)}">${esc(sm)}</div>`:''}${rt?'<div style="font-size:11px;color:var(--t2);margin-top:4px">运行时凭证不支持删除</div>':''}<div class="fc-sep"></div></div><div class="fc-body">${qH}</div></div>`}

function renderQC(p,c){if(c.error)return`<div class="qe">错误: ${esc(c.error)}</div>`;if(!c.data)return'<div class="qempty" style="cursor:default">暂无数据</div>';if(p==='claude')return rCl(c.data);if(p==='codex')return rCo(c.data);if(p==='gemini-cli')return rGe(c.data);if(p==='antigravity')return rAn(c.data);if(p==='kimi')return rKi(c.data);return'<div class="qempty" style="cursor:default">不支持</div>'}
function rCl(d){const w=[];Object.entries(d.limits||{}).forEach(([k,v])=>{if(v&&typeof v==='object'&&'utilization'in v){const u=v.utilization||0,r=Math.max(0,100-u),c=u>70?'h':u>30?'m':'l';w.push(`<div class="qi"><div class="qih"><span class="ql">${fCWL(k)}</span><span class="qv" style="color:${r<30?'var(--err)':'inherit'}">${r.toFixed(0)}%</span></div><div class="pbar"><div class="pfill ${c}" style="width:${r}%"></div></div>${v.resets_at?`<div class="qm">重置于 ${fmtTs(v.resets_at)}</div>`:''}</div>`)}});return w.join('')||'<div class="qempty" style="cursor:default">暂无</div>'}
function rCo(d){const rl=d.rate_limit||d.rateLimit||{},w=[];const pw=rl.primary_window||rl.primaryWindow;if(pw){const u=pw.used_percent||pw.usedPercent||0,r=100-u,c=u>70?'h':u>30?'m':'l';const rt=pw.reset_at||pw.reset_time||pw.reset_at_timestamp;w.push(`<div class="qi"><div class="qih"><span class="ql">5小时</span><span class="qv" style="color:${r<30?'var(--err)':'inherit'}">${r.toFixed(0)}%</span></div><div class="pbar"><div class="pfill ${c}" style="width:${r}%"></div></div>${rt?`<div class="qm">恢复于 ${fmtResetTime(rt)}</div>`:''}</div>`)}const sw=rl.secondary_window||rl.secondaryWindow;if(sw){const u=sw.used_percent||sw.usedPercent||0,r=100-u,c=u>70?'h':u>30?'m':'l';const rt=sw.reset_at||sw.reset_time||sw.reset_at_timestamp;w.push(`<div class="qi"><div class="qih"><span class="ql">周</span><span class="qv" style="color:${r<30?'var(--err)':'inherit'}">${r.toFixed(0)}%</span></div><div class="pbar"><div class="pfill ${c}" style="width:${r}%"></div></div>${rt?`<div class="qm">恢复于 ${fmtResetTime(rt)}</div>`:''}</div>`)}return w.join('')||'<div class="qempty" style="cursor:default">暂无</div>'}
function rGe(d){const bs=d.buckets||[];if(!bs.length)return'<div class="qempty" style="cursor:default">暂无</div>';return bs.slice(0,5).map(b=>{const r=(b.remaining_fraction??b.remainingFraction??0)*100,c=r<30?'h':r<70?'m':'l';const rt=b.resetTime||b.reset_time;return`<div class="qi"><div class="qih"><span class="ql" style="max-width:130px;overflow:hidden;text-overflow:ellipsis">${esc(b.model_id||b.modelId||'?')}</span><span class="qv" style="color:${r<30?'var(--err)':'inherit'}">${r.toFixed(0)}%</span></div><div class="pbar"><div class="pfill ${c}" style="width:${r}%"></div></div>${rt?`<div class="qm">恢复于 ${fmtResetTime(rt)}</div>`:''}</div>`}).join('')}
function rAn(d){if(!d?.models)return'<div class="qempty" style="cursor:default">暂无</div>';return Object.entries(d.models).slice(0,5).map(([k,v])=>{if(!v||typeof v!=='object')return'';const p=(v.remaining_fraction??v.remainingFraction??0)*100,c=p<30?'h':p<70?'m':'l';const rt=v.resetTime||v.reset_time;return`<div class="qi"><div class="qih"><span class="ql" style="max-width:130px;overflow:hidden;text-overflow:ellipsis">${esc(k)}</span><span class="qv" style="color:${p<30?'var(--err)':'inherit'}">${p.toFixed(0)}%</span></div><div class="pbar"><div class="pfill ${c}" style="width:${p}%"></div></div>${rt?`<div class="qm">恢复于 ${fmtResetTime(rt)}</div>`:''}</div>`}).filter(Boolean).join('')||'<div class="qempty" style="cursor:default">暂无</div>'}
function rKi(d){if(!Array.isArray(d))return'<div class="qempty" style="cursor:default">暂无</div>';return d.slice(0,5).map(i=>{const u=i.used||0,l=i.limit||0,r=l>0?Math.max(0,100-(u/l*100)):100,c=r<30?'h':r<70?'m':'l';return`<div class="qi"><div class="qih"><span class="ql">${esc(i.label||i.model||'?')}</span><span class="qv" style="color:${r<30?'var(--err)':'inherit'}">${r.toFixed(0)}%</span></div><div class="pbar"><div class="pfill ${c}" style="width:${r}%"></div></div>${l>0?`<div class="qm">${u}/${l}</div>`:''}</div>`}).join('')||'<div class="qempty" style="cursor:default">暂无</div>'}
function fCWL(k){return{primary:'5小时',secondary:'周',five_hour:'5h',seven_day:'7天',seven_day_oauth_apps:'OAuth 7天',seven_day_opus:'Opus 7天',seven_day_sonnet:'Sonnet 7天',seven_day_cowork:'Cowork 7天',monthly:'月限',month:'月限',monthly_limit:'月限',iguana_necktie:'Pro限时'}[k]||k.replace(/_/g,' ')}
function fmtPlan(p){return normPlan(p)||String(p||'').trim()}

function refSingle(sid,fn){const s=servers.find(x=>x.id===sid);if(!s)return;const f=(s.files||[]).find(x=>x.name===fn);if(!f)return;refQ(s,f)}
function showToast(msg){const t=document.getElementById('toast');t.innerHTML=`<span class="ld" style="width:12px;height:12px;border-width:2px"></span>${msg}`;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2000)}
function hideDlCredModal(){document.getElementById('dlCredModal').classList.add('hidden');dlCredCtx=null}
function showDlCredModal(sid,fn,p){if(np(p)!=='codex'){dlFile(sid,fn);return}dlCredCtx={sid,fn};const msg=document.getElementById('dlCredMsg');if(msg)msg.textContent=`选择下载 ${fn} 的 CPA凭证文件，或转换为 Codex CLI 使用的 auth.json 格式。`;document.getElementById('dlCredModal').classList.remove('hidden')}
function saveBlob(fn,blob){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=fn;a.click();setTimeout(()=>URL.revokeObjectURL(u),0)}
async function fetchCredResp(sid,fn){const s=servers.find(x=>x.id===sid);if(!s)throw new Error('服务端不存在');return cpaHttp(cpaUrl(s,'/auth-files/download',{name:fn,_ts:Date.now()}),{headers:{'Authorization':cpaAuth(s),'Cache-Control':'no-cache','Pragma':'no-cache'},responseType:'base64'})}
async function dlFile(sid,fn){try{const r=await fetchCredResp(sid,fn);saveBlob(fn,cpaBlob(r,r.headers?.['content-type']||'application/octet-stream'))}catch(e){alert('下载失败: '+e.message)}}
function toCodexAuthJson(raw){const src=raw&&typeof raw.tokens==='object'&&raw.tokens?raw.tokens:raw||{},idToken=String(src.id_token||'').trim(),accessToken=String(src.access_token||'').trim(),refreshToken=String(src.refresh_token||'').trim(),accountId=(src.account_id??src.chatgpt_account_id??exCId(raw))||null;if(!idToken||!accessToken||!refreshToken)throw new Error('当前凭证不包含完整的 Codex OAuth Token');const out={OPENAI_API_KEY:null,tokens:{id_token:idToken,access_token:accessToken,refresh_token:refreshToken,account_id:accountId},last_refresh:raw?.last_refresh||raw?.lastRefresh||null};if(raw?.auth_mode)out.auth_mode=raw.auth_mode;if(raw?.agent_identity)out.agent_identity=raw.agent_identity;return out}
async function downloadCredOriginal(){const c=dlCredCtx;if(!c)return;hideDlCredModal();await dlFile(c.sid,c.fn)}
async function downloadCredCodex(){const c=dlCredCtx;if(!c)return;hideDlCredModal();try{const r=await fetchCredResp(c.sid,c.fn),raw=JSON.parse(cpaTextFromBase64(r)),out=toCodexAuthJson(raw);saveBlob('auth.json',new Blob([JSON.stringify(out,null,2)],{type:'application/json'}))}catch(e){showToast('转换下载失败: '+e.message)}}
async function setCredDisabled(sid,fn,disabled){const s=servers.find(x=>x.id===sid),k=ck(sid,fn),act=disabled?'禁用':'启用';if(!s||s.status!=='online'||togglingCreds.has(k))return;if(!confirm(`确定要${act}凭证 "${fn}" 吗？`))return;togglingCreds.add(k);renderCur();try{await cpaHttp(cpaUrl(s,'/auth-files/status'),{method:'PATCH',headers:{'Authorization':cpaAuth(s),'Content-Type':'application/json'},body:JSON.stringify({name:fn,disabled})});showToast(disabled?'已禁用':'已启用');await connectSrv(s)}catch(e){showToast(act+'失败: '+e.message)}finally{togglingCreds.delete(k);renderCur()}}
async function delCred(sid,fn){const s=servers.find(x=>x.id===sid),k=ck(sid,fn),f=s?.files?.find(x=>x.name===fn),src=String(f?.source||'').trim().toLowerCase();if(!s||s.status!=='online'||deletingCreds.has(k)||togglingCreds.has(k)||loadingFiles.has(k))return;if(isRtOnly(f)||src==='memory'){showToast('运行时凭证不支持删除');return}if(!confirm(`确定要删除凭证 "${fn}" 吗？`))return;deletingCreds.add(k);renderCur();try{await cpaHttp(cpaUrl(s,'/auth-files',{name:fn}),{method:'DELETE',headers:{'Authorization':cpaAuth(s)}});delete quotaCache[k];loadingFiles.delete(k);showToast('已删除');await connectSrv(s)}catch(e){showToast('删除失败: '+e.message)}finally{deletingCreds.delete(k);renderCur()}}
function showAddModal(){editId=null;document.getElementById('mt2').textContent='添加 CPA';document.getElementById('sn').value='';document.getElementById('su').value='';document.getElementById('sk').value='';document.getElementById('sModal').classList.remove('hidden')}
function showEditModal(id){srvMenuId=null;const s=servers.find(x=>x.id===id);if(!s)return;editId=id;document.getElementById('mt2').textContent='编辑 CPA';document.getElementById('sn').value=s.name;document.getElementById('su').value=s.url;document.getElementById('sk').value=s.key;document.getElementById('sModal').classList.remove('hidden')}
function hideSModal(){document.getElementById('sModal').classList.add('hidden');editId=null}
function cleanUrlText(u){return String(u||'').trim().replace(/[\u200B-\u200D\uFEFF]/g,'').replace(/\s+/g,'')}
function stripTrailingSlash(u){return cleanUrlText(u).replace(/\/+$/,'')}
function withDefaultScheme(u,scheme){const s=cleanUrlText(u);if(!s)return'';if(s.startsWith('//'))return scheme+':'+s;return !/^[a-z][a-z0-9+.-]*:\/\//i.test(s)?scheme+'://'+s:s}
function setDefaultPort(u,port){try{const r=new URL(u);if(!r.port)r.port=String(port);return r.toString().replace(/\/+$/,'')}catch{return u&&!u.match(/:\d+(\/|$)/)?u+':'+port:u}}
function joinUrl(base,path,query){const b=stripTrailingSlash(base),p='/'+String(path||'').replace(/^\/+/,''),u=b+p;if(!query)return u;const qs=new URLSearchParams();Object.entries(query).forEach(([k,v])=>{if(v!==undefined&&v!==null)qs.set(k,String(v))});const s=qs.toString();return s?u+'?'+s:u}
function normHttpUrl(u,scheme='https'){return stripTrailingSlash(withDefaultScheme(u,scheme))}
function normCpaUrl(u){let s=cleanUrlText(u).replace(/\/v0\/management\/?$/,'').replace(/\/+$/,'');if(!s)return'';return setDefaultPort(normHttpUrl(s,'http'),8317)}
function cpaUrl(srv,path,query){srv.url=normCpaUrl(srv.url);return joinUrl(srv.url,'/v0/management/'+String(path||'').replace(/^\/+/,''),query)}
function cpaEndpointUrl(srv){return normCpaUrl(srv.url)}
function cpaManagementUrl(srv){return joinUrl(cpaEndpointUrl(srv),'/management.html')}
function hrefUrl(u,base=''){const s=cleanUrlText(u);if(!s)return'';if(s.startsWith('//'))return'https:'+s;if(/^https?:\/\//i.test(s))return s;if(base)return joinUrl(base,s);return normHttpUrl(s,'https')}
function topupHref(raw,base=''){if(raw==null||typeof raw!=='string')return'';const s=cleanUrlText(raw),bad=new Set(['null','undefined','false','none','nan','0','-','无','暂无']);if(!s||bad.has(s.toLowerCase())||/^[#?]/.test(s))return'';const manual=!!cleanUrlText(base);if(!manual&&s.startsWith('/'))return'';const u=hrefUrl(s,base);try{const r=new URL(u),path=r.pathname.replace(/\/+$/,'').toLowerCase();if(!/^https?:$/.test(r.protocol)||path===''||path==='/')return'';if(path==='/api'||path.startsWith('/api/'))return'';return u}catch{return''}}
function channelTopupHref(c,d={}){return topupHref(d.topupUrlManual||c.manual?.topupUrl||'',c.url)}
function saveSrv(){const n=document.getElementById('sn').value.trim(),u=document.getElementById('su').value.trim(),k=cleanSecretText(document.getElementById('sk').value);if(!n||!u||!k){alert('请填写名称、地址和管理密钥');return}let nu=normCpaUrl(u),target=null;if(editId){const s=servers.find(x=>x.id===editId);if(s){s.name=n;s.url=nu;s.key=k;s.status=null;s.files=[];target=s}}else{target={id:Date.now().toString(),name:n,url:nu,key:k,status:null,files:[]};servers.push(target)}save();hideSModal();renderCur();if(target)connectSrv(target).then(()=>renderCur())}
function delSrv(id){srvMenuId=null;const s=servers.find(x=>x.id===id);if(!s)return;document.getElementById('dmsg').textContent=`确定要删除 "${s.name}" 吗？`;delId=id;document.getElementById('dModal').classList.remove('hidden')}
function hideDModal(){document.getElementById('dModal').classList.add('hidden');delId=null}
function confirmDel(){if(delId){servers=servers.filter(s=>s.id!==delId);save();showToast('CPA 已删除');renderCur()}hideDModal()}

let addCredSrvId=null,oauthPollTimer=null,oauthState=null,oauthProviderName='',oauthProviderId='';
const OAUTH_PROVIDERS=[
  {id:'anthropic',name:'Claude',path:'/anthropic-auth-url',icon:'i-claude'},
  {id:'codex',name:'Codex',path:'/codex-auth-url',icon:'i-codex'},
  {id:'gemini-cli',name:'Gemini CLI',path:'/gemini-cli-auth-url',icon:'i-gemini'},
  {id:'antigravity',name:'Antigravity',path:'/antigravity-auth-url',icon:'i-antigravity'}
];
function showAddCredModal(sid){addCredSrvId=sid;const s=servers.find(x=>x.id===sid);if(!s)return;document.getElementById('addCredSrv').textContent='— '+s.name;document.getElementById('oauthBtns').innerHTML=OAUTH_PROVIDERS.map(p=>`<button class="b bs bsm keep-label oauth-btn" onclick="startOAuth('${p.id}','${p.path}','${p.name}')" title="${esc(p.name)}" aria-label="${esc(p.name)}">${icon(p.icon)}<span>${esc(p.name)}</span></button>`).join('');document.getElementById('credFile').value='';document.getElementById('oauthStep1').classList.remove('hidden');document.getElementById('oauthStep2').classList.add('hidden');document.getElementById('addCredModal').classList.remove('hidden')}
function hideAddCredModal(){document.getElementById('addCredModal').classList.add('hidden');clearInterval(oauthPollTimer);oauthPollTimer=null;oauthState=null;oauthProviderName='';oauthProviderId='';addCredSrvId=null}
async function startOAuth(pid,path,name){const s=servers.find(x=>x.id===addCredSrvId);if(!s)return;try{const r=await cpaHttp(cpaUrl(s,path,{is_webui:true}),{headers:{'Authorization':cpaAuth(s)}}),d=cpaJson(r);const url=d.url||d.auth_url||d.authUrl;if(!url)throw new Error('No URL');oauthState=d.state||null;oauthProviderName=name;oauthProviderId=pid;document.getElementById('oauthProvider').textContent=name;document.getElementById('oauthUrl').textContent=url;document.getElementById('oauthPolling').innerHTML='<span class="ld" style="width:10px;height:10px;border-width:1.5px"></span> 等待授权中...';document.getElementById('callbackUrl').value='';document.getElementById('oauthStep1').classList.add('hidden');document.getElementById('oauthStep2').classList.remove('hidden');clearInterval(oauthPollTimer);if(oauthState){oauthPollTimer=setInterval(()=>pollOAuth(s),3000)}}catch(e){showToast('OAuth 启动失败: '+e.message)}}
async function pollOAuth(s){if(!oauthState)return;try{const r=await cpaHttp(cpaUrl(s,'/get-auth-status',{state:oauthState}),{headers:{'Authorization':cpaAuth(s)}}),d=cpaJson(r);if(d.status==='ok'){clearInterval(oauthPollTimer);oauthPollTimer=null;document.getElementById('oauthPolling').innerHTML='<span style="color:var(--ok)">✓ 授权成功</span>';showToast(oauthProviderName+' 授权成功');await connectSrv(s);renderCur()}else if(d.status==='error'){clearInterval(oauthPollTimer);oauthPollTimer=null;document.getElementById('oauthPolling').innerHTML=`<span style="color:var(--err)">✗ 授权失败: ${esc(d.error||'未知错误')}</span>`}}catch{}}
function copyOAuthUrl(){copyText(document.getElementById('oauthUrl').textContent)}
function fallbackCopy(t){const ta=document.createElement('textarea');ta.value=t;ta.style.cssText='position:fixed;left:-9999px';document.body.appendChild(ta);ta.select();try{document.execCommand('copy');showToast('已复制')}catch{showToast('复制失败')}document.body.removeChild(ta)}
function copyText(t){host.copyText(t).then(res=>{if(res?.ok)showToast('已复制');else fallbackCopy(t)}).catch(()=>fallbackCopy(t))}
function endpointRow(url){return`<div class="endpoint-row"><div><div class="endpoint-label">端点 URL</div><code class="endpoint-url">${esc(url)}</code></div>${ib('bs','复制',`copyText(${jsArg(url)})`)}</div>`}
