async function submitCallback(){const s=servers.find(x=>x.id===addCredSrvId);if(!s)return;const url=cleanUrlText(document.getElementById('callbackUrl').value);if(!url){showToast('请输入回调 URL');return}const providerMap={'gemini-cli':'gemini'};const provider=providerMap[oauthProviderId]||oauthProviderId;try{await cpaHttp(cpaUrl(s,'/oauth-callback'),{method:'POST',headers:{'Authorization':cpaAuth(s),'Content-Type':'application/json'},body:JSON.stringify({provider,redirect_url:url,state:oauthState||''})});showToast('回调提交成功');clearInterval(oauthPollTimer);oauthPollTimer=null;document.getElementById('oauthPolling').innerHTML='<span style="color:var(--ok)">✓ 授权成功</span>';await connectSrv(s);renderCur()}catch(e){showToast('回调提交失败: '+e.message)}}
async function uploadCredFile(){const s=servers.find(x=>x.id===addCredSrvId);if(!s)return;const fi=document.getElementById('credFile');if(!fi.files||!fi.files.length){showToast('请选择文件');return}try{const mp=await multipartFileBody('file',fi.files[0]);await cpaHttp(cpaUrl(s,'/auth-files'),{method:'POST',headers:{'Authorization':cpaAuth(s),'Content-Type':`multipart/form-data; boundary=${mp.boundary}`},bodyBase64:mp.bodyBase64});showToast('上传成功');await connectSrv(s);hideAddCredModal();renderCur()}catch(e){showToast('上传失败: '+e.message)}}

