function normBaseUrl(u,type){let s=normHttpUrl(u,'https');if(!s)return'';if(type==='sub2api')s=s.replace(/\/api\/v1\/?$/,'');else s=s.replace(/\/api\/?$/,'');return stripTrailingSlash(s)}
function chAuthHeaders(c){const h={'Content-Type':'application/json','Cache-Control':'no-cache','Pragma':'no-cache'},sys=c.type==='newapi'&&c.authMode==='system',t=cleanBearerText(sys?c.systemToken:c.token),uid=String(sys?c.systemUserId:c.userId||'').trim(),ck=cleanCookieText(c.type==='newapi'?authSession.cookieWithoutName(c.cookie,'new_api_refresh'):c.cookie||'');if(t)h.Authorization=/^Bearer\s+/i.test(t)?t:'Bearer '+t;if(ck&&!sys)h.Cookie=ck;if(c.type==='newapi'&&uid)h['New-Api-User']=uid;return h}
function isTurnstileError(e){return/(turnstile|cf-turnstile|TURNSTILE_VERIFICATION_FAILED|verification failed|captcha)/i.test(String(e?.message||e||''))}
function isBrowserSessionExpiredError(e){return/(BROWSER_SESSION_REVALIDATION_REQUIRED|浏览器会话验证已过期)/i.test(String(e?.message||e||''))}
function isCloudflareBlockedError(e){return/(CLOUDFLARE_CHALLENGE_BLOCKED|Cloudflare 验证拦截|Just a moment|cf-mitigated|challenge-platform|cf-turnstile)/i.test(String(e?.message||e||''))}
function headerValue(headers,name){const lower=String(name).toLowerCase();for(const [k,v]of Object.entries(headers||{})){if(String(k).toLowerCase()===lower)return String(v||'')}return''}
function isCloudflareChallengeResponse(res){const status=Number(res?.status)||0,body=String(res?.body||''),lower=body.toLowerCase(),ct=headerValue(res?.headers,'content-type').toLowerCase(),mit=headerValue(res?.headers,'cf-mitigated').toLowerCase();if(mit.includes('challenge'))return true;const html=ct.includes('text/html')||lower.includes('<html');return[403,429,503].includes(status)&&html&&/(just a moment|verify you are human|verifying you are human|checking your browser|managed challenge|challenge-platform|cdn-cgi\/challenge-platform|__cf_chl|cf-chl|cf-turnstile|cf-browser-verification|cloudflare ray id)/i.test(body)}
function browserSessionExpiredError(){return new Error('BROWSER_SESSION_REVALIDATION_REQUIRED: 浏览器会话验证已过期，请在登录窗口或浏览器标签页完成验证后重试')}
function cloudflareBlockedError(){return new Error('CLOUDFLARE_CHALLENGE_BLOCKED: Cloudflare 验证拦截；请开启浏览器请求模式或在站点 WAF 放行 API')}
async function chReq(c,path,opt={}){c.url=normBaseUrl(c.url,c.type);const useBrowserFetch=channelBrowserFetch(c),baseHeaders=chAuthHeaders(c);if(useBrowserFetch)delete baseHeaders.Cookie;const res=await chHttp(joinUrl(c.url,path),{method:opt.method||'GET',headers:{...baseHeaders,...(opt.headers||{})},body:opt.body||null,browserFetch:useBrowserFetch,siteUrl:c.url,siteType:c.type,username:useBrowserFetch?c.username:'',password:useBrowserFetch?c.password:'',requestId:opt.requestId||''});const text=res.body;let j=text;if(typeof text==='string'&&text){try{j=JSON.parse(text)}catch{j=text}}if(!res.ok){if(isCloudflareChallengeResponse(res))throw useBrowserFetch?browserSessionExpiredError():cloudflareBlockedError();const msg=res.error||j&&typeof j==='object'&&(j.message||j.detail)||typeof j==='string'&&j;throw new Error(`HTTP ${res.status}${msg?': '+msg:''}`)}if(j&&typeof j==='object'&&'code'in j){if(j.code!==0)throw new Error(j.message||j.detail||'请求失败');return j.data}if(j&&typeof j==='object'&&'success'in j){if(!j.success)throw new Error(j.message||'请求失败');return 'data'in j?j.data:j}return j}
function unwrapItems(d){if(Array.isArray(d))return d;if(Array.isArray(d?.items))return d.items;if(Array.isArray(d?.data?.items))return d.data.items;return[]}
function isAuthSessionLimitError(e){return/(AUTH_SESSION_LIMIT|AUTH_SESSION_ISSUANCE_LIMIT|会话.{0,12}(上限|已满|过多|限制)|session.{0,12}(limit|maximum|too many))/i.test(String(e?.message||e||''))}
function isAuthSessionMismatchError(e){return/(AUTH_SESSION_MISMATCH|会话.{0,16}不匹配|账号与渠道不一致)/i.test(String(e?.message||e||''))}
function chErr(e){const msg=e&&e.message?String(e.message):String(e||'未知错误');if(isAuthSessionLimitError(msg))return'NewAPI 登录会话已达上限。请先关闭该渠道自动刷新，并在站点撤销其他会话；仍无法登录时重置密码后手动刷新';if(isBrowserSessionExpiredError(msg))return`浏览器会话验证已过期；请在${hostCapText('loginTargetName','登录页')}完成验证后重试`;if(isCloudflareBlockedError(msg))return'Cloudflare 验证拦截；请开启浏览器请求模式或在站点 WAF 放行 API';if(isTurnstileError(msg))return'登录被 Turnstile 拦截；可填写访问令牌兜底，或在站点后台获取可用令牌后同步';if(/HTTP\s*401/.test(msg))return'HTTP 401: 登录会话无效、访问令牌无效或用户 ID 不匹配，请检查渠道认证信息';if(/HTTP\s*429/.test(msg))return'HTTP 429: 站点限流，已减少重复请求，请稍后手动刷新';return msg}
function chRedeemPath(c){return c.type==='sub2api'?'/api/v1/redeem':'/api/user/topup'}
function chRedeemPayload(c,code){return c.type==='sub2api'?{code}:{key:code}}
function chRedeemResultText(c,d){const v=d&&typeof d==='object'&&'data'in d?d.data:d;if(c.type==='newapi'&&(typeof v==='number'||(typeof v==='string'&&v.trim()&&Number.isFinite(Number(v)))))return`，到账 ${fmtNewQuota(v,c.data?.status||{})}`;if(!v||typeof v!=='object')return'';const t=String(v.type||'').toLowerCase(),n=v.value??v.amount;if((t==='balance'||t==='')&&n!=null&&Number.isFinite(Number(n)))return`，到账 ${fmtMoney(n)}`;if(t==='concurrency'&&n!=null&&Number.isFinite(Number(n)))return`，并发 +${fmtNum(n,0)}`;if(t==='subscription')return'，订阅已生效';if(v.new_balance!=null&&Number.isFinite(Number(v.new_balance)))return`，余额 ${fmtMoney(v.new_balance)}`;return''}
function setChRedeemBusy(v){chRedeeming=v;const b=document.getElementById('chRedeemBtn'),i=document.getElementById('chRedeemCode');if(i)i.disabled=v;if(b){b.disabled=v;b.innerHTML=v?'<span class="ld" style="width:14px;height:14px;border-width:2px"></span>':icon('i-redeem');b.dataset.iconized='兑换';b.classList.add('icon-only','icon-btn')}}
function showChRedeemModal(id){const c=channels.find(x=>x.id===id);if(!c)return;chRedeemId=id;chMenuId=null;document.querySelectorAll('.srv-menu').forEach(x=>x.classList.add('hidden'));const title=document.getElementById('chRedeemTitle'),code=document.getElementById('chRedeemCode'),msg=document.getElementById('chRedeemMsg');if(title)title.textContent='— '+c.name;if(code)code.value='';if(msg)msg.textContent='';setChRedeemBusy(false);document.getElementById('chRedeemModal').classList.remove('hidden');setTimeout(()=>document.getElementById('chRedeemCode')?.focus(),0)}
function hideChRedeemModal(){if(chRedeeming)return;document.getElementById('chRedeemModal').classList.add('hidden');chRedeemId=null;setChRedeemBusy(false)}
async function postChRedeem(c,code){return chReq(c,chRedeemPath(c),{method:'POST',body:JSON.stringify(chRedeemPayload(c,code))})}
async function ensureChRedeemReady(c){if(c.status==='online')return;await connectChannel(c);if(c.status!=='online')throw new Error(c.error||chConfigError(c))}
async function submitChRedeem(){if(chRedeeming)return;const c=channels.find(x=>x.id===chRedeemId),code=cleanSecretText(document.getElementById('chRedeemCode')?.value||'');if(!c)return;if(!code){showToast('请输入兑换码');return}setChRedeemBusy(true);try{await ensureChRedeemReady(c);let data;try{data=await postChRedeem(c,code)}catch(e){if(!/HTTP\s*401/.test(String(e?.message||e)))throw e;c.status=null;await ensureChRedeemReady(c);data=await postChRedeem(c,code)}document.getElementById('chRedeemModal').classList.add('hidden');chRedeemId=null;showToast('兑换成功'+chRedeemResultText(c,data));await connectChannel(c);renderCur()}catch(e){showToast('兑换失败: '+chErr(e))}finally{setChRedeemBusy(false)}}
function isRateLimited(c){return c.type==='newapi'&&/HTTP\s*429/.test(String(c.error||''))&&Date.now()-(c.updatedAt||0)<60000}
function pickUserId(x){const d=x&&typeof x==='object'?x:null;return d?.id??d?.user_id??d?.userId??d?.data?.id??d?.data?.user_id??d?.data?.userId??d?.user?.id??''}
function todaySecRange(){const d=new Date();d.setHours(0,0,0,0);return{start:Math.floor(d.getTime()/1000),end:Math.floor(Date.now()/1000)}}
function todayDateRange(){const d=new Date(),s=new Date(d);s.setHours(0,0,0,0);const f=x=>x.toISOString().slice(0,10);return{start:f(s),end:f(d)}}
function sumArr(a,k){return(a||[]).reduce((n,x)=>n+(Number(x?.[k])||0),0)}
function fmtNum(n,d=2){if(n==null||n===''||Number.isNaN(Number(n)))return'-';const v=Number(n);if(Math.abs(v)>=1000000)return(v/1000000).toFixed(1)+'M';if(Math.abs(v)>=1000)return(v/1000).toFixed(1)+'K';return Number.isInteger(v)?String(v):v.toFixed(d)}
function fmtMoney(n){if(n==null||n===''||Number.isNaN(Number(n)))return'-';return '$'+Number(n).toFixed(2)}
function fmtRatio(v){const n=ratioNumber(v);return n==null?'-':n.toFixed(4).replace(/0+$/,'').replace(/\.$/,'')+'x'}
function ratioNumber(v){const n=Number(String(v??'').trim().replace(/x$/i,''));return Number.isFinite(n)&&n>0?n:null}
function channelRechargeRatio(d){return ratioNumber(d?.rechargeRatioManual)??ratioNumber(d?.rechargeRatio)}
function channelActualMultiplier(c,nominal){const n=ratioNumber(nominal),r=channelRechargeRatio(c?.data||c);return n==null?null:r==null?n:n/r}
function channelRatioText(c,nominal){const actual=channelActualMultiplier(c,nominal);return actual==null?'':fmtRatio(actual)}
function scaleChannelValue(d,value){if(value==null||(typeof value==='string'&&!value.trim()))return value;const n=Number(value),r=channelRechargeRatio(d);return Number.isFinite(n)&&r? n/r:value}
function fmtNewQuota(raw,status){if(raw==null||(typeof raw==='string'&&!raw.trim())||Number.isNaN(Number(raw)))return'-';const q=Number(raw),qpu=Number(status?.quota_per_unit)||500000,typ=String(status?.quota_display_type||'USD').toUpperCase();if(typ==='TOKENS')return fmtNum(q,0)+' 点';const usd=q/qpu;if(typ==='CNY')return '¥'+(usd*(Number(status?.usd_exchange_rate)||1)).toFixed(2);if(typ==='CUSTOM'){const sym=status?.custom_currency_symbol||'¤',rate=Number(status?.custom_currency_exchange_rate)||1;return sym+(usd*rate).toFixed(2)}return fmtMoney(usd)}
function cleanManual(m,baseUrl=''){const out={};const rr=String(m?.rechargeRatio??'').trim();if(rr)out.rechargeRatio=rr;const topup=cleanUrlText(m?.topupUrl??'');if(topup)out.topupUrl=/^https?:\/\//i.test(topup)||!baseUrl?normHttpUrl(topup,'https'):joinUrl(baseUrl,topup);return out}
function chLoginReady(c){return !!(String(c.username||'').trim()&&String(c.password||'').trim())}
function chSystemReady(c){return c.type==='newapi'&&!!cleanBearerText(c.systemToken||'')}
function chSub2TokenReady(c){return c.type==='sub2api'&&!!(cleanBearerText(c.token||'')||cleanSecretText(c.refreshToken||''))}
function chNewApiRefreshReady(c){return c.type==='newapi'&&!!authSession.cookieValue(c.cookie,'new_api_refresh')}
function chNewApiSessionReady(c){return c.type==='newapi'&&!!(cleanBearerText(c.token||'')||cleanCookieText(c.cookie||'')||String(c.userId||'').trim())}
function chCanAuto(c){return !!(String(c.url||'').trim()&&(c.type==='newapi'?(chLoginReady(c)||chSystemReady(c)||chNewApiSessionReady(c)):(chLoginReady(c)||chSub2TokenReady(c))))}
function chConfigError(c){if(!String(c.url||'').trim())return'请填写站点地址';if(c.type==='newapi')return'New API 请填写账号密码或系统访问令牌';return'Sub2API 请填写用户名和密码，或读取/填写访问令牌作为兜底'}
function applyManual(d,c){const m=c.manual||{};return{...(d||{}),manual:m,topupUrlManual:m.topupUrl,rechargeRatioManual:m.rechargeRatio}}
function pickToken(x){if(!x)return'';if(typeof x==='string')return x;return x.token||x.access_token||x.accessToken||x.access_token_string||x.accessTokenString||x.jwt||x.id_token||x.key||x.api_key||x.data?.token||x.data?.access_token||x.data?.accessToken||x.data?.jwt||x.user?.token||x.user?.access_token||''}
function pickRefreshToken(x){if(!x||typeof x==='string')return'';return x.refresh_token||x.refreshToken||x.data?.refresh_token||x.data?.refreshToken||x.user?.refresh_token||x.user?.refreshToken||''}
function pickExpiresIn(x){if(!x||typeof x==='string')return 0;return Number(x.expires_in??x.expiresIn??x.data?.expires_in??x.data?.expiresIn)||0}
function sub2TokenExpiring(c){const exp=Number(c.tokenExpiresAt)||0;return !cleanBearerText(c.token||'')||!!(exp&&Date.now()>exp-60000)}
