async function extFetch(payload){return host.fetch(payload)}
function channelLoginPayload(){const type=document.getElementById('chType')?.value||'newapi',siteUrl=normBaseUrl(document.getElementById('chUrl')?.value||'',type);return{siteType:type,siteUrl,username:document.getElementById('chUser')?.value?.trim()||'',password:document.getElementById('chPass')?.value||''}}
function openSiteLogin(){if(!hostCap('siteLogin')){showToast('当前端等待接入登录页打开能力');return}const p=channelLoginPayload();if(!p.siteUrl){showToast('请先填写站点地址');return}const target=hostCapText('loginTargetName','登录页'),browserMode=document.getElementById('chBrowserFetch')?.checked===true&&hostCap('browserFetch'),okMsg=browserMode?`${target}已打开，完成登录后保持会话即可刷新；读取令牌会更新兜底配置`:`${target}已打开，完成验证后点击读取令牌`;host.openSiteLogin(p).then(res=>showToast(res?.ok?okMsg:'打开登录页失败: '+(res?.error||'未知错误'))).catch(e=>showToast('打开登录页失败: '+(e?.message||e)))}
function readSiteTokens(){if(!hostCap('siteTokenRead')){showToast('当前端等待接入读取令牌能力');return}const p=channelLoginPayload();if(!p.siteUrl){showToast('请先填写站点地址');return}host.readSiteTokens(p.siteUrl,p.siteType).then(applySiteTokensResult).catch(e=>applySiteTokensResult({ok:false,error:e?.message||String(e)}))}
function applySiteTokensResult(res){if(!res.ok){showToast('读取令牌失败: '+(res.error||'未知错误'));return}const type=document.getElementById('chType')?.value||'newapi',access=cleanBearerText(res.auth_token||res.access_token||''),refresh=cleanSecretText(res.refresh_token||''),cookie=cleanCookieText(res.cookie||''),exp=Number(res.token_expires_at)||0,userId=String(res.user_id||res.userId||'').trim(),st=document.getElementById('chSystemToken'),rt=document.getElementById('chRefreshToken'),su=document.getElementById('chSystemUserId');if(!access&&!refresh&&!cookie){showToast(`当前${hostCapText('tokenSourceName','登录页')}未找到令牌`);return}if(st&&access)st.value=access;if(rt&&refresh)rt.value=refresh;if(su&&userId)su.value=userId;if(st){st.dataset.expiresAt=String(exp||0);st.dataset.cookie=cookie;st.dataset.cookieType=type;st.dataset.readUserId=userId;st.dataset.readUserIdType=type}if(type==='newapi')showToast(userId?'已读取访问令牌和用户 ID':'已读取访问令牌，请确认用户 ID');else showToast(refresh?'已读取访问令牌和刷新令牌':'已读取访问令牌')}
function bytesToBase64(bytes){let binary='';for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(binary)}
async function cpaHttp(url,opt={}){const payload={kind:'cpa',url,method:opt.method||'GET',headers:opt.headers||{},body:opt.body||null,bodyBase64:opt.bodyBase64||'',responseType:opt.responseType||''};const j=await extFetch(payload);if(!j)throw new Error(inExtensionPage?'CPA 请求未经过扩展外壳，请关闭旧页面后从扩展弹窗或侧边栏重新打开':'CPA 请求需要通过浏览器扩展后台发送');if(!j.ok){let msg=j.error||`HTTP ${j.status}`;if(j.body)msg+=' '+String(j.body).slice(0,160);throw new Error(msg)}return j}
function cpaJson(res){const text=res.body;return typeof text==='string'&&text?JSON.parse(text):text}
function cpaBlob(res,type='application/octet-stream'){const bin=Uint8Array.from(atob(res.body||''),c=>c.charCodeAt(0));return new Blob([bin],{type})}
function cpaTextFromBase64(res){const bytes=Uint8Array.from(atob(res.body||''),c=>c.charCodeAt(0));return new TextDecoder().decode(bytes)}
async function fileToBase64(file){return bytesToBase64(new Uint8Array(await file.arrayBuffer()))}
async function multipartFileBody(name,file){const boundary='----RelayHub'+Date.now().toString(16)+Math.random().toString(16).slice(2),safeName=file.name.replace(/"/g,''),pre=`--${boundary}\r\nContent-Disposition: form-data; name="${name}"; filename="${safeName}"\r\nContent-Type: ${file.type||'application/octet-stream'}\r\n\r\n`,post=`\r\n--${boundary}--\r\n`;return{boundary,bodyBase64:await fileToBase64(new Blob([pre,file,post]))}}
async function chExtFetch(payload){return extFetch(payload)}
