function chMonitorStatusLabel(status){return{operational:'正常',degraded:'波动',failed:'失败',error:'错误',unknown:'暂无数据'}[status]||'暂无数据'}
function chMonitorPct(value){if(value==null||value==='')return'-';const n=Number(value);return Number.isFinite(n)?n.toFixed(n>=99?2:1)+'%':'-'}
function chMonitorMs(value){if(value==null||value==='')return'-';const n=Number(value);return Number.isFinite(n)?(n>=1000?(n/1000).toFixed(2)+' s':Math.round(n)+' ms'):'-'}
function chMonitorTps(value){if(value==null||value==='')return'-';const n=Number(value);return Number.isFinite(n)?n.toFixed(1):'-'}
function chMonitorStatus(status){const s=channelMonitor.normalizeStatus(status);return`<span class="monitor-status ${s}">${chMonitorStatusLabel(s)}</span>`}
