function hideMonitorTickTip(){document.getElementById('monitorTickTip')?.remove()}
function showMonitorTickTip(el){if(!el)return;hideMonitorTickTip();const rows=[['时间',el.dataset.time],['状态',el.dataset.status],['成功率',el.dataset.rate],['缓存率',el.dataset.cache],['完整延迟',el.dataset.latency],['首 token',el.dataset.ttft],['网络延迟',el.dataset.ping],['TPS',el.dataset.tps]].filter(([,v])=>v&&v!=='-'),tip=document.createElement('div');tip.id='monitorTickTip';tip.className='monitor-tick-tip';tip.setAttribute('role','tooltip');tip.innerHTML=rows.map(([k,v])=>`<span>${esc(k)}</span><strong>${esc(v)}</strong>`).join('');document.body.appendChild(tip);const r=el.getBoundingClientRect(),tw=tip.offsetWidth,th=tip.offsetHeight;let top=r.top-th-8;if(top<8)top=r.bottom+8;if(top<8)top=8;const left=Math.min(window.innerWidth-tw-8,Math.max(8,r.left+r.width/2-tw/2));tip.style.left=left+'px';tip.style.top=top+'px'}
