async function ensureChMonitorReady(c){if(c.status!=='online')await connectChannel(c);if(c.status!=='online')throw new Error(c.error||chConfigError(c))}
const coordinateChMonitorRecovery=channelMonitor.createRecoveryCoordinator();
async function recoverChMonitor(c,version){return coordinateChMonitorRecovery.recover(c.id,version,async()=>{c.status=null;await connectChannel(c);if(c.status!=='online')throw new Error(c.error||'渠道认证恢复失败')})}
