async function fetchChMonitor(c){await ensureChMonitorReady(c);if(c.type==='sub2api')return fetchSub2Monitor(c);const summary=await chMonitorReq(c,'/api/perf-metrics/summary?hours=24');return{kind:'newapi',rows:channelMonitor.normalizeNewApi(summary),metricsAvailable:true,metricsError:''}}
async function loadChMonitor(manual=false){const c=channels.find(x=>x.id===chMonitorId),box=document.getElementById('chMonitorContent');if(!c||!box||chMonitorLoading)return;const seq=++chMonitorRequestSeq;setChMonitorBusy(true);box.innerHTML=chMonitorLoadingHtml(manual?'正在刷新监控':'加载监控中');try{const data=await fetchChMonitor(c);if(seq!==chMonitorRequestSeq||chMonitorId!==c.id)return;chMonitorData=data;chMonitorDetails={};chMonitorDetailExpanded.clear();renderChMonitor();if(manual)showToast('监控已刷新')}catch(e){if(seq===chMonitorRequestSeq&&chMonitorId===c.id)box.innerHTML=chMonitorErrorHtml(e)}finally{if(seq===chMonitorRequestSeq&&chMonitorId===c.id)setChMonitorBusy(false)}}
function filterChMonitor(value){chMonitorQuery=String(value||'');renderChMonitor()}
function chMonitorMatches(values){const q=chMonitorQuery.trim().toLowerCase();return!q||values.join(' ').toLowerCase().includes(q)}
function renderChMonitor(){const box=document.getElementById('chMonitorContent'),c=channels.find(x=>x.id===chMonitorId),data=chMonitorData;if(!box||!c||!data)return;if(data.kind==='sub2api')renderSub2Monitor(c,box,data);else if(data.kind==='sub2api-v2')renderSub2V2Monitor(c,box,data);else renderNewApiMonitor(c,box,data);scheduleIconize()}
function monitorDetailButton(onclick,loading,label='查看分组监控'){return`<button class="monitor-expand keep-icon" onclick="${onclick}" ${loading?'disabled':''} title="${esc(label)}" aria-label="${esc(label)}">${loading?'<span class="ld" style="width:13px;height:13px;border-width:2px"></span>':icon('i-chevron-down')}</button>`}
function renderNewApiMonitor(c,box,data){const rows=data.rows.filter(r=>chMonitorMatches([r.model,r.status]));const list=rows.map(r=>{const key=String(r.model),expanded=chMonitorDetailExpanded.has(key),detail=expanded?chMonitorDetails[key]:null,loading=expanded&&chMonitorDetailLoading.has(key),detailHtml=loading?`<div class="monitor-groups">${chMonitorLoadingHtml('加载分组监控')}</div>`:detail?renderNewApiMonitorDetail(c,detail):'';return`<section class="monitor-model"><div class="monitor-model-head">${chMonitorIdentity(r.model,r.status)}${monitorDetailButton(`toggleNewApiMonitorDetail(${jsArg(r.model)})`,loading,expanded?'收起分组监控':'查看分组监控')}</div>${chMonitorValues([{label:'成功率',value:chMonitorPct(r.successRate)},{label:'平均延迟',value:r.latencyMs==null?null:chMonitorMs(r.latencyMs)},{label:'平均 TPS',value:r.tps==null?null:chMonitorTps(r.tps)}])}${detailHtml}</section>`}).join('');box.innerHTML=`<div class="monitor-list">${list||(chMonitorQuery?'<div class="monitor-empty">没有匹配的模型</div>':'<div class="monitor-empty">最近 24 小时暂无模型性能数据</div>')}</div>`}
function renderNewApiMonitorDetail(c,detail){const groups=detail.groups.map(g=>`<article class="monitor-row">${chMonitorIdentity(chMonitorGroupLabel(c,g.name),g.status)}${chMonitorValues([{label:'成功率',value:g.successRate==null?null:chMonitorPct(g.successRate)},{label:'首 token',value:g.ttftMs==null?null:chMonitorMs(g.ttftMs)},{label:'平均延迟',value:g.latencyMs==null?null:chMonitorMs(g.latencyMs)},{label:'平均 TPS',value:g.tps==null?null:chMonitorTps(g.tps)}])}${chMonitorTimeline(channelMonitor.buildBucketTimeline(g.timeline,{rangeSeconds:86400,maxSlots:48,end:Date.now()}))}</article>`).join('');return`<div class="monitor-groups">${groups||'<div class="monitor-empty">该模型暂无分组时间序列</div>'}</div>`}
async function toggleNewApiMonitorDetail(model){const key=String(model);if(chMonitorDetailExpanded.has(key)){chMonitorDetailExpanded.delete(key);hideMonitorTickTip();renderChMonitor();return}chMonitorDetailExpanded.add(key);if(chMonitorDetails[key]){renderChMonitor();return}const c=channels.find(x=>x.id===chMonitorId);if(!c||c.type!=='newapi'||chMonitorDetailLoading.has(key))return;const seq=chMonitorRequestSeq;chMonitorDetailLoading.add(key);renderChMonitor();try{const raw=await chMonitorReq(c,`/api/perf-metrics?model=${encodeURIComponent(model)}&hours=24`);if(seq===chMonitorRequestSeq&&chMonitorId===c.id)chMonitorDetails[key]=channelMonitor.normalizeNewApiDetail(raw)}catch(e){chMonitorDetailExpanded.delete(key);if(seq===chMonitorRequestSeq)showToast('时间线读取失败: '+chErr(e))}finally{chMonitorDetailLoading.delete(key);if(seq===chMonitorRequestSeq&&chMonitorId===c.id)renderChMonitor()}}
function renderSub2V2Monitor(c,box,data){const rows=data.rows.filter(r=>chMonitorMatches([r.name,r.provider,r.group,r.groupId,r.status])),coverage=data.coverage||data.summary?.coverage||{},bucketSeconds=Number(coverage.bucket_seconds)||300,end=coverage.requested_end||coverage.data_through;const list=rows.map(r=>`<article class="monitor-row">${chMonitorIdentity(chMonitorGroupLabel(c,r.name||r.provider,r.groupId,data.groups),r.status,[r.provider])}${chMonitorValues([{label:'成功率',value:r.successRate==null?null:chMonitorPct(r.successRate)},{label:'缓存率',value:r.cacheRate==null?null:chMonitorPct(r.cacheRate)},{label:'首 token P50',value:r.ttftMs==null?null:chMonitorMs(r.ttftMs)},{label:'平均延迟',value:r.latencyMs==null?null:chMonitorMs(r.latencyMs)},{label:'TPS',value:r.tps==null?null:chMonitorTps(r.tps)}])}${chMonitorTimeline(channelMonitor.buildBucketTimeline(r.timeline,{bucketSeconds,rangeSeconds:5400,maxSlots:48,end}))}</article>`).join('');box.innerHTML=`<div class="monitor-list">${list||(chMonitorQuery?'<div class="monitor-empty">没有匹配的分组</div>':'<div class="monitor-empty">V2 暂无分组监控数据</div>')}</div>`}
function renderSub2Monitor(c,box,data){const rows=data.rows.filter(r=>chMonitorMatches([r.name,r.provider,r.group,r.primaryModel,...r.extraModels.map(m=>m.model)]));const list=rows.map(r=>`<article class="monitor-row">${chMonitorIdentity(chMonitorGroupLabel(c,r.group||r.name||r.primaryModel,r.groupId,data.groups),r.status,[r.provider])}${chMonitorValues([{label:'主模型',value:r.primaryModel||null,title:r.primaryModel},{label:'7 天可用率',value:r.availability7d==null?null:chMonitorPct(r.availability7d)},{label:'响应延迟',value:r.latencyMs==null?null:chMonitorMs(r.latencyMs)},{label:'网络延迟',value:r.pingLatencyMs==null?null:chMonitorMs(r.pingLatencyMs)}])}${chMonitorTimeline(channelMonitor.buildProbeTimeline(r.timeline))}</article>`).join('');box.innerHTML=`<div class="monitor-list">${list||(chMonitorQuery?'<div class="monitor-empty">没有匹配的分组</div>':'<div class="monitor-empty">暂无分组监控数据</div>')}</div>`}

async function showChKeys(id){const c=channels.find(x=>x.id===id);if(!c)return;chKeyId=id;chKeys=[];chKeyFull={};chKeyGroups=[];chKeyEditId=null;document.getElementById('chKeyTitle').textContent='— '+c.name;document.getElementById('chKeyLoading').classList.remove('hidden');document.getElementById('chKeyContent').classList.add('hidden');document.getElementById('chKeyContent').innerHTML='';document.getElementById('chKeyModal').classList.remove('hidden');await loadChKeys()}
function hideChKeys(){document.getElementById('chKeyModal').classList.add('hidden');hideChKeyTestModal(true);chKeyId=null;chKeys=[];chKeyFull={};chKeyGroups=[];chKeyEditId=null}
function chKeyEndpoint(c,qs=''){return c.type==='sub2api'?`/api/v1/keys${qs}`:`/api/token/${qs}`}
function chKeyListPath(c){return c.type==='sub2api'?'/api/v1/keys?page=1&page_size=100':'/api/token/?p=1&size=100'}
function chEndpointUrl(c){return joinUrl(c.url,'/v1')}
function chKeyGroupName(k){const g=k.group;if(g&&typeof g==='object')return String(g.name||g.id||'');return String(g||k.Group?.name||'')}
function chKeyStatus(k){const s=k.status;if(typeof s==='string')return s==='active'?'启用':s==='inactive'?'禁用':s;return{1:'启用',2:'禁用',3:'过期',4:'耗尽',0:'禁用'}[Number(s)]||'未知'}
function chKeyStatusClass(k){return chKeyStatus(k)==='启用'?'bdg-ok':'bdg-err'}
function normalizeChKey(c,k){if(c.type==='sub2api'){const g=k.group||k.Group||{};const total=Number(k.quota)||0,used=Number(k.quota_used)||0;return{id:k.id,name:k.name||'未命名密钥',key:k.key||'',status:k.status,group:g.name||'',groupId:k.group_id||g.id||'',unlimited_quota:total<=0,remain_quota:Math.max(total-used,0),used_quota:used,raw:k}}return{...k,raw:k}}
async function testChannelGroup(channelId,group,event){event?.stopPropagation?.();const c=channels.find(x=>x.id===channelId);if(!c)return;try{if(c.status!=='online')await connectChannel(c);if(c.status!=='online')throw new Error(c.error||chConfigError(c));chKeyId=c.id;chKeys=[];chKeyFull={};chKeyGroups=[];await loadChKeyGroups(c);const raw=await chReq(c,chKeyListPath(c));chKeys=unwrapItems(raw).map(k=>normalizeChKey(c,k));const matches=chKeys.filter(k=>chKeyGroupName(k)===group),key=matches.find(k=>chKeyStatus(k)==='启用')||matches[0];if(!key)throw new Error('该分组没有可测试的 key');await showChKeyTestModal(String(key.id))}catch(e){showToast('无法打开分组测试: '+chErr(e))}}
async function loadChKeyGroups(c){const known=channelGroups(c);if(c.type==='sub2api'){const [gs,rates]=await Promise.all([chReq(c,'/api/v1/groups/available').catch(()=>[]),chReq(c,'/api/v1/groups/rates').catch(()=>null)]),available=mergeSub2AvailableGroups(gs,rates);chKeyGroups=(Array.isArray(available)?available:[]).map(g=>{const label=g.name||String(g.id),m=known.find(x=>x.label===label);return{label,id:g.id,ratio:g.rate_multiplier??g.user_rate_multiplier??g.ratio??m?.ratio}}).filter(g=>g.label);return}chKeyGroups=known.map(g=>({label:g.label,id:g.label,ratio:g.ratio}))}
async function loadChKeys(){const c=channels.find(x=>x.id===chKeyId),box=document.getElementById('chKeyContent');if(!c||!box)return;chKeysLoading=true;try{if(c.status!=='online')await connectChannel(c);await loadChKeyGroups(c);const d=await chReq(c,chKeyListPath(c));chKeys=unwrapItems(d).map(k=>normalizeChKey(c,k));if(c.data)c.data.keyGroups=chKeyGroupLabels(c,chKeys,c.data.groups);renderChKeys();renderChannels()}catch(e){box.innerHTML=`<div class="empty">${esc(chErr(e))}</div>`}finally{chKeysLoading=false;document.getElementById('chKeyLoading').classList.add('hidden');box.classList.remove('hidden');scheduleIconize()}}
function chKeyGroupInfo(c,name){const n=String(name||'');return chKeyGroups.find(g=>g.label===n)||channelGroups(c).find(g=>g.label===n)||null}
function chKeyGroupLabel(c,name){const info=chKeyGroupInfo(c,name),label=name||'未分组',ratio=channelRatioText(c,info?.ratio);return ratio?`[${ratio}] ${label}`:label}
function chKeyGroupOptions(c,current=''){return[...new Set([...chKeyGroups.map(g=>g.label),current].filter(Boolean))]}
function renderChKeyToolbar(c){const opts=chKeyGroupOptions(c);return`<div class="key-create"><input class="fi" id="newKeyName" placeholder="新密钥名称" value=""><select class="fi" id="newKeyGroup" ${opts.length?'':'disabled'}>${opts.length?opts.map(o=>`<option value="${esc(o)}">${esc(chKeyGroupLabel(c,o))}</option>`).join(''):'<option value="">无可用分组</option>'}</select>${ib('bp','新增',`createChKey()`,opts.length?'':'disabled')}</div>`}
function renderChKeys(){const box=document.getElementById('chKeyContent'),c=channels.find(x=>x.id===chKeyId);if(!box||!c)return;const list=chKeys.length?chKeys.map(k=>renderChKeyItem(c,k)).join(''):'<div class="empty">暂无密钥</div>';box.innerHTML=endpointRow(chEndpointUrl(c))+renderChKeyToolbar(c)+list;scheduleIconize()}
function renderChKeyItem(c,k){const id=String(k.id),secret=chKeyFull[id]||'',keyText=maskSecret(k.key||secret),group=chKeyGroupName(k),editing=String(chKeyEditId)===id,opts=chKeyGroupOptions(c,group),nameId=keyDomId('keyName',id),groupId=keyDomId('chg',id);const title=editing?`<input class="fi key-edit-name" id="${nameId}" value="${esc(k.name||'')}">`:`<span class="key-name">${esc(k.name||'未命名密钥')}</span>`;const groupView=editing?`<select class="fi key-edit-group" id="${groupId}">${opts.map(o=>`<option value="${esc(o)}" ${o===group?'selected':''}>${esc(chKeyGroupLabel(c,o))}</option>`).join('')}</select>`:`<span class="bdg key-group">${esc(chKeyGroupLabel(c,group))}</span>`;const actions=editing?`${ib('bp','保存',`saveChKey(${jsArg(id)})`)}${ib('bs','取消',`cancelChKeyEdit()`)}`:`${ib('bs','测试',`showChKeyTestModal(${jsArg(id)})`)}${ib('bs','复制',`copyChKey(${jsArg(id)})`)}${ib('bs','编辑',`editChKey(${jsArg(id)})`)}${ib('bd','删除',`deleteChKey(${jsArg(id)})`)}`;return`<div class="key-row"><div class="key-info"><div class="key-line"><span class="key-line-label">名称</span>${title}</div><div class="key-line"><span class="key-line-label">分组</span>${groupView}</div><div class="key-line key-secret-line"><span class="key-line-label">Key</span><code class="key-secret">${keyText}</code></div></div><div class="ch-actions key-actions">${actions}</div></div>`}
function editChKey(id){chKeyEditId=id;renderChKeys()}
function cancelChKeyEdit(){chKeyEditId=null;renderChKeys()}
function groupIdForName(name){return chKeyGroups.find(g=>g.label===name)?.id}
function groupIdPayload(v){return/^\d+$/.test(String(v))?Number(v):v}
function keyPayload(c,k,name,group){if(c.type==='sub2api'){const gid=groupIdForName(group),hasGroup=gid!==undefined&&gid!==null&&gid!=='';return{name:name||k.name||'key',...(hasGroup?{group_id:groupIdPayload(gid)}:{})}}return{...k.raw,...k,name:name||k.name,group}}
function legacySub2KeyPayload(k,body){return{...body,quota:Number(k.raw?.quota??k.remain_quota??0)||0,ip_whitelist:Array.isArray(k.raw?.ip_whitelist)?k.raw.ip_whitelist:[]}}
async function ensureChKeyFull(id,opt={}){const c=channels.find(x=>x.id===chKeyId),k=chKeys.find(x=>String(x.id)===String(id));if(!c||!k)return'';if(chKeyFull[id])return chKeyFull[id];if(c.type==='newapi'){const d=await chReq(c,`/api/token/${id}/key`,{method:'POST',requestId:opt.requestId||''});chKeyFull[id]=d?.key||d?.data?.key||''}else chKeyFull[id]=k.key||'';if(!chKeyFull[id])throw new Error('未返回密钥');return chKeyFull[id]}
async function copyChKey(id){try{const key=await ensureChKeyFull(id);if(!key)return;copyText(key)}catch{copyText(chKeyFull[id]||'')}}
function parseChModels(raw){const list=Array.isArray(raw?.data)?raw.data:Array.isArray(raw)?raw:Array.isArray(raw?.models)?raw.models:[];return[...new Set(list.map(x=>typeof x==='string'?x:(x?.id||x?.name||x?.model)).filter(Boolean).map(String))].sort((a,b)=>a.localeCompare(b))}
function setChKeyTestBusy(v){chKeyTesting=v;const b=document.getElementById('chKeyTestBtn'),m=document.getElementById('chKeyTestModel');if(m)m.disabled=v;if(b){b.disabled=v;b.innerHTML=v?'<span class="ld" style="width:14px;height:14px;border-width:2px"></span>':icon('i-play');b.dataset.iconized='测试';b.classList.add('icon-only','icon-btn')}}
function renderChKeyModelMenu(models,query=''){const q=String(query||'').trim().toLowerCase(),items=[...new Set(models||[])].filter(x=>!q||String(x).toLowerCase().includes(q)).slice(0,80);return items.length?items.map(x=>`<button type="button" class="model-option" onclick="pickChKeyModel(${jsArg(x)})" title="${esc(x)}">${esc(x)}</button>`).join(''):'<div class="model-empty">无匹配模型</div>'}
function refreshChKeyModelMenu(open=true){const menu=document.getElementById('chKeyModelMenu'),inp=document.getElementById('chKeyTestModel'),ctx=chKeyTestCtx;if(!menu||!inp||!ctx)return;menu.innerHTML=renderChKeyModelMenu(ctx.models||[],inp.value);menu.classList.toggle('hidden',!open||!(ctx.models||[]).length)}
function pickChKeyModel(model){const inp=document.getElementById('chKeyTestModel');if(inp)inp.value=model;refreshChKeyModelMenu(false)}
function setChKeyTestResult(html){const el=document.getElementById('chKeyTestResult');if(el)el.innerHTML=html||''}
function nextChKeyTestRequestId(){return'ch_key_test_'+Date.now()+'_'+Math.random().toString(16).slice(2)}
function trackChKeyTestRequest(id){if(id)chKeyTestRequests.add(id);return id}
function untrackChKeyTestRequest(id){if(id)chKeyTestRequests.delete(id)}
function cancelChKeyTestRequests(){chKeyTestRequests.forEach(id=>host.cancelFetch?.(id));chKeyTestRequests.clear()}
function hideChKeyTestModal(force=false){if(chKeyTesting&&!force){cancelChKeyTestRequests();showToast('已取消测试')}else cancelChKeyTestRequests();document.getElementById('chKeyTestModal')?.classList.add('hidden');refreshChKeyModelMenu(false);chKeyTestCtx=null;setChKeyTestBusy(false)}
function chKeyTestAlive(ctx){return !!ctx&&chKeyTestCtx===ctx&&!document.getElementById('chKeyTestModal')?.classList.contains('hidden')}
async function showChKeyTestModal(id){const c=channels.find(x=>x.id===chKeyId),k=chKeys.find(x=>String(x.id)===String(id));if(!c||!k)return;cancelChKeyTestRequests();const ctx={channelId:c.id,keyId:String(id),models:[]};chKeyTestCtx=ctx;document.getElementById('chKeyTestTitle').textContent='— '+(k.name||id);const inp=document.getElementById('chKeyTestModel'),hint=document.getElementById('chKeyTestHint');if(inp){inp.value='';inp.placeholder='加载模型中...';inp.disabled=true}refreshChKeyModelMenu(false);if(hint)hint.textContent='正在从 /v1/models 获取模型列表';setChKeyTestResult('');setChKeyTestBusy(false);document.getElementById('chKeyTestModal').classList.remove('hidden');const requestId=trackChKeyTestRequest(nextChKeyTestRequestId());try{const key=await ensureChKeyFull(id,{requestId}),raw=await chKeyApiReq(c,key,'/v1/models',{method:'GET',requestId}),models=parseChModels(raw);if(!chKeyTestAlive(ctx))return;ctx.models=models;if(inp){inp.disabled=false;inp.placeholder='选择或输入模型';inp.value='';inp.focus()}refreshChKeyModelMenu(document.activeElement===inp&&!!models.length);if(hint)hint.textContent=models.length?'已获取模型列表，请选择或输入模型':'模型列表为空，请输入模型'}catch(e){if(!chKeyTestAlive(ctx))return;if(String(e?.message||e).includes('取消'))return;if(inp){inp.disabled=false;inp.placeholder='输入模型';inp.focus()}refreshChKeyModelMenu(false);if(hint)hint.textContent='模型列表获取失败，请输入模型';setChKeyTestResult(`<div class="qe">模型获取失败: ${esc(chErr(e))}</div>`)}finally{untrackChKeyTestRequest(requestId)}}
function chKeySelectedModel(){return cleanUrlText(document.getElementById('chKeyTestModel')?.value||'')}
async function chKeyApiReq(c,key,path,opt={}){const headers={'Authorization':/^Bearer\s+/i.test(key)?key:'Bearer '+key,'Content-Type':'application/json','Accept':'application/json, text/event-stream, */*','Cache-Control':'no-cache','Pragma':'no-cache'},res=await chHttp(joinUrl(c.url,path),{kind:'channel-key',method:opt.method||'GET',headers,body:opt.body||null,browserFetch:false,streamTiming:opt.streamTiming===true,requestId:opt.requestId||''});let j=res.body;if(typeof j==='string'&&j){try{j=JSON.parse(j)}catch{}}if(res.streamTiming)j=j&&typeof j==='object'?{...j,streamTiming:res.streamTiming}:{body:j,streamTiming:res.streamTiming};if(!res.ok){if(isCloudflareChallengeResponse(res))throw cloudflareBlockedError();const msg=res.error||j&&typeof j==='object'&&(j.error?.message||j.message||j.detail)||typeof j==='string'&&j;throw new Error(`HTTP ${res.status}${msg?': '+msg:''}`)}return j}
function fmtSeconds(ms){return ms==null?'-':(Number(ms)/1000).toFixed(2)+' s'}
async function runChKeyTest(){if(chKeyTesting)return;const ctx=chKeyTestCtx,c=channels.find(x=>x.id===ctx?.channelId);if(!ctx||!c)return;const model=chKeySelectedModel();if(!model){showToast('请选择或输入模型');return}setChKeyTestBusy(true);setChKeyTestResult('<div class="qload"><span class="ld"></span>测试中</div>');const started=performance.now(),requestId=trackChKeyTestRequest(nextChKeyTestRequestId());try{const key=await ensureChKeyFull(ctx.keyId,{requestId}),body=JSON.stringify({model,messages:[{role:'system',content:'你是一个简洁的中文助手。'},{role:'user',content:'请用一句话介绍你当前是否可以正常响应。'}],temperature:0.2,max_tokens:64,stream:true}),res=await chKeyApiReq(c,key,'/v1/chat/completions',{method:'POST',body,streamTiming:true,requestId});if(!chKeyTestAlive(ctx))return;const ok=!!res?.streamTiming?.firstTokenMs||!!res?.streamTiming?.totalMs||!!res,timing=res?.streamTiming||{},totalMs=timing.totalMs??Math.round(performance.now()-started),ft=fmtSeconds(timing.firstTokenMs),total=fmtSeconds(totalMs),sample=String(timing.sample||res?.choices?.[0]?.message?.content||'').trim();setChKeyTestResult(`<div class="test-result ${ok?'ok':'err'}"><div><span class="bdg ${ok?'bdg-ok':'bdg-err'}">${ok?'成功':'失败'}</span></div><div class="test-metrics"><span>首 token <strong>${esc(ft)}</strong></span><span>总耗时 <strong>${esc(total)}</strong></span></div>${sample?`<code>${esc(sample.slice(0,240))}</code>`:''}</div>`)}catch(e){if(chKeyTestAlive(ctx)&&!String(e?.message||e).includes('取消'))setChKeyTestResult(`<div class="test-result err"><div><span class="bdg bdg-err">失败</span></div><div class="qe">${esc(chErr(e))}</div></div>`)}finally{untrackChKeyTestRequest(requestId);if(chKeyTestAlive(ctx))setChKeyTestBusy(false)}}
async function saveChKey(id){const c=channels.find(x=>x.id===chKeyId),k=chKeys.find(x=>String(x.id)===String(id)),sel=document.getElementById(keyDomId('chg',id)),inp=document.getElementById(keyDomId('keyName',id));if(!c||!k||!sel)return;try{const body=keyPayload(c,k,inp?.value?.trim(),sel.value),path=c.type==='sub2api'?`/api/v1/keys/${id}`:'/api/token/';try{await chReq(c,path,{method:'PUT',body:JSON.stringify(body)})}catch(e){if(c.type!=='sub2api'||!/HTTP\s*400/.test(String(e?.message||e)))throw e;await chReq(c,path,{method:'PUT',body:JSON.stringify(legacySub2KeyPayload(k,body))})}showToast('密钥已保存');chKeyEditId=null;await loadChKeys()}catch(e){showToast('保存失败: '+chErr(e))}}
async function createChKey(){const c=channels.find(x=>x.id===chKeyId),name=document.getElementById('newKeyName')?.value?.trim()||'new-key',group=document.getElementById('newKeyGroup')?.value||'';if(!c)return;if(!group){showToast('没有可用分组');return}try{let body;if(c.type==='sub2api'){const gid=groupIdForName(group);if(gid===undefined||gid===null||gid===''){showToast('请选择有效分组');return}body={name,quota:0,ip_whitelist:[],group_id:groupIdPayload(gid)}}else body={name,group,remain_quota:0,expired_time:-1,unlimited_quota:true,model_limits_enabled:false,model_limits:'',allow_ips:'',cross_group_retry:false};await chReq(c,c.type==='sub2api'?'/api/v1/keys':'/api/token/',{method:'POST',body:JSON.stringify(body)});showToast('密钥已新增');await loadChKeys()}catch(e){showToast('新增失败: '+chErr(e))}}
async function deleteChKey(id){const c=channels.find(x=>x.id===chKeyId),k=chKeys.find(x=>String(x.id)===String(id));if(!c||!k)return;if(!confirm(`确定删除密钥 "${k.name||id}" 吗？`))return;try{await chReq(c,c.type==='sub2api'?`/api/v1/keys/${id}`:`/api/token/${id}`,{method:'DELETE'});showToast('密钥已删除');await loadChKeys()}catch(e){showToast('删除失败: '+chErr(e))}}

/* ============ API KEY MANAGEMENT ============ */
let akSrvId=null,akKeys=[];
function showApiKeyModal(sid){akSrvId=sid;const s=servers.find(x=>x.id===sid);if(!s||s.status!=='online')return;document.getElementById('akSrvName').textContent='— '+s.name;document.getElementById('akLoading').classList.remove('hidden');document.getElementById('akContent').classList.add('hidden');document.getElementById('akNewKey').value='';document.getElementById('apiKeyModal').classList.remove('hidden');fetchApiKeys()}
function hideApiKeyModal(){document.getElementById('apiKeyModal').classList.add('hidden');akSrvId=null;akKeys=[]}
async function fetchApiKeys(){const s=servers.find(x=>x.id===akSrvId);if(!s)return;try{const d=cpaJson(await cpaHttp(cpaUrl(s,'/api-keys'),{headers:{'Authorization':cpaAuth(s)}}));akKeys=d['api-keys']||[];renderAkList()}catch(e){akKeys=[];renderAkList();showToast('获取失败: '+e.message)}finally{document.getElementById('akLoading').classList.add('hidden');document.getElementById('akContent').classList.remove('hidden')}}
function renderAkList(){const el=document.getElementById('akList'),s=servers.find(x=>x.id===akSrvId);if(!el)return;const head=s?endpointRow(cpaEndpointUrl(s)):'';if(!akKeys.length){el.innerHTML=head+'<div style="text-align:center;padding:20px;color:var(--t2);font-size:12px">暂无 API Key</div>';return}
el.innerHTML=head+akKeys.map((k,i)=>{const masked=k.length>12?k.slice(0,4)+'****'+k.slice(-4):k.slice(0,2)+'****';return`<div class="ak-row" id="akr_${i}"><span class="ak-val"><span class="ak-masked">${esc(masked)}</span><span class="ak-full">${esc(k)}</span></span><button class="b bs bsm" onclick="toggleAkFull(${i})" title="显示/隐藏">👁</button><button class="b bs bsm" onclick="copyAk(${i})" title="复制">📋</button><button class="b bd bsm" onclick="delAk(${i})" title="删除">✕</button></div>`}).join('')}
function toggleAkFull(i){const r=document.getElementById('akr_'+i);if(r)r.classList.toggle('show-full')}
function copyAk(i){if(!akKeys[i])return;copyText(akKeys[i])}
async function delAk(i){const s=servers.find(x=>x.id===akSrvId);if(!s)return;try{await cpaHttp(cpaUrl(s,'/api-keys',{index:i}),{method:'DELETE',headers:{'Authorization':cpaAuth(s)}});showToast('已删除');await fetchApiKeys()}catch(e){showToast('删除失败: '+e.message)}}
async function addApiKey(){const s=servers.find(x=>x.id===akSrvId);if(!s)return;const v=document.getElementById('akNewKey').value.trim();if(!v){showToast('请输入 API Key');return}const newKeys=[...akKeys,v];try{await cpaHttp(cpaUrl(s,'/api-keys'),{method:'PUT',headers:{'Authorization':cpaAuth(s),'Content-Type':'application/json'},body:JSON.stringify(newKeys)});document.getElementById('akNewKey').value='';showToast('已添加');await fetchApiKeys()}catch(e){showToast('添加失败: '+e.message)}}
function genApiKey(){const cs='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';const a=new Uint8Array(17);crypto.getRandomValues(a);const k='sk-'+Array.from(a,b=>cs[b%cs.length]).join('');document.getElementById('akNewKey').value=k}

/* ============ SETTINGS MODAL ============ */
let stSrvId=null;
const SETTINGS_ENDPOINTS=[{key:'proxy-url',path:'proxy-url',configPath:'proxy-url',label:'代理 URL',type:'text',placeholder:'例如: socks5://user:pass@host:1080/'},{key:'request-retry',path:'request-retry',configPath:'request-retry',label:'请求重试次数',type:'number',placeholder:'0'},{key:'routing/strategy',path:'routing/strategy',configPath:'routing/strategy',responseKeys:['strategy','routing-strategy'],fallbackPaths:['routing'],label:'路由策略',type:'select',options:[{v:'round-robin',l:'round-robin (轮询)'},{v:'fill-first',l:'fill-first (填满优先)'}]}];
function showSrvSettings(sid){stSrvId=sid;const s=servers.find(x=>x.id===sid);if(!s||s.status!=='online')return;document.getElementById('stSrvName').textContent='— '+s.name;document.getElementById('stLoading').classList.remove('hidden');document.getElementById('stContent').classList.add('hidden');document.getElementById('settingsModal').classList.remove('hidden');loadSettingsCfg()}
function hideSettingsModal(){document.getElementById('settingsModal').classList.add('hidden');stSrvId=null}
function stObj(v){return v&&typeof v==='object'&&!Array.isArray(v)?v:null}
function stPathValue(obj,path){let cur=obj;for(const part of String(path||'').split('/').filter(Boolean)){const o=stObj(cur);if(!o||!Object.prototype.hasOwnProperty.call(o,part))return undefined;cur=o[part]}return cur}
function stPick(raw,ep,configMode){if(raw===undefined||raw===null)return undefined;const obj=stObj(raw);if(!obj)return raw;const paths=[configMode?ep.configPath:ep.key,ep.key,...(ep.responseKeys||[])].filter(Boolean);for(const path of paths){const v=String(path).includes('/')?stPathValue(obj,path):(Object.prototype.hasOwnProperty.call(obj,path)?obj[path]:undefined);if(v!==undefined)return v}if(Object.prototype.hasOwnProperty.call(obj,'value'))return obj.value;if(Object.prototype.hasOwnProperty.call(obj,'data'))return stPick(obj.data,ep,configMode);return undefined}
function stDisplay(v){return v===null?'不支持':(v===''||v===undefined?'未设置':String(v))}
async function stFetchJson(s,path){return cpaJson(await cpaHttp(cpaUrl(s,path,{_ts:Date.now()}),{headers:{'Authorization':cpaAuth(s),'Cache-Control':'no-cache','Pragma':'no-cache'}}))}
async function stFetchConfig(s){try{return await stFetchJson(s,'config')}catch{return null}}
async function stLoadValue(s,ep,fullCfg){const cv=stPick(fullCfg,ep,true);if(cv!==undefined)return cv;for(const path of [ep.path,...(ep.fallbackPaths||[])]){try{const v=stPick(await stFetchJson(s,path),ep,false);if(v!==undefined)return v}catch{}}return null}
function stSelectOptions(ep,v){const sv=String(v??''),opts=[...(ep.options||[])];if(sv&&!opts.some(o=>o.v===sv))opts.unshift({v:sv,l:sv+' (当前值)'});return opts.map(o=>`<option value="${esc(o.v)}" ${sv===o.v?'selected':''}>${esc(o.l)}</option>`).join('')}
async function loadSettingsCfg(){const s=servers.find(x=>x.id===stSrvId),c=document.getElementById('stContent'),l=document.getElementById('stLoading');if(!s)return;if(l)l.classList.remove('hidden');if(c)c.classList.add('hidden');const fullCfg=await stFetchConfig(s),cfg={};await Promise.allSettled(SETTINGS_ENDPOINTS.map(async ep=>{cfg[ep.key]=await stLoadValue(s,ep,fullCfg)}));if(!c)return;let h='';SETTINGS_ENDPOINTS.forEach(ep=>{const v=cfg[ep.key],cur=stDisplay(v);h+=`<div class="setting-card"><div class="setting-head"><div><div class="setting-label">${ep.label}</div><div class="setting-current">当前：${esc(cur)}</div></div></div>`;
if(v===null){h+=`<div class="setting-empty">此服务端不支持该配置</div>`}else if(ep.type==='select'){h+=`<div class="setting-control"><select class="fi" id="st_${ep.key}">${stSelectOptions(ep,v)}</select><button class="b bp icon-btn keep-icon" onclick="saveStCfg('${ep.key}','${ep.path}')" title="保存" aria-label="保存">${icon('i-check')}</button></div>`}else{h+=`<div class="setting-control"><input class="fi" id="st_${ep.key}" type="${ep.type}" value="${esc(v==null?'':String(v))}" placeholder="${ep.placeholder}"><button class="b bp icon-btn keep-icon" onclick="saveStCfg('${ep.key}','${ep.path}')" title="保存" aria-label="保存">${icon('i-check')}</button></div>`}
h+='</div>'});c.innerHTML=h;if(l)l.classList.add('hidden');c.classList.remove('hidden')}
async function saveStCfg(key,path){const s=servers.find(x=>x.id===stSrvId);if(!s)return;const inp=document.getElementById('st_'+key);if(!inp)return;let v=key==='proxy-url'?cleanUrlText(inp.value):inp.value.trim();if(inp.type==='number')v=Number.isFinite(parseInt(v,10))?parseInt(v,10):0;try{await cpaHttp(cpaUrl(s,path),{method:'PUT',headers:{'Authorization':cpaAuth(s),'Content-Type':'application/json'},body:JSON.stringify({value:v})});showToast('保存成功');loadSettingsCfg()}catch(e){showToast('保存失败: '+e.message)}}
